// N2 문제: bank_vocab_a
export default [
  {id: "kj-001",type: "kanji",q: "現状を正確に〔把握〕してから対策を考えよう。",opts: ["はあく","ばあく","はおく","はくあく"],a: 0,why: ["정답. 把握(はあく) = 파악","把는 탁음이 아닌 「は」로 읽는다.","握(あく)를 屋(おく)와 혼동한 읽기.","把를 「はく」로 읽는 음은 없다."],ko: "현재 상황을 정확하게 파악한 뒤에 대책을 생각하자.",ref: ["v:把握"]},
  {id: "kj-002",type: "kanji",q: "「自由」という〔概念〕は、国によって少しずつ違う。",opts: ["かいねん","がいねん","がいにん","がいれん"],a: 1,why: ["概는 탁음 「がい」. 청음으로 읽으면 틀린다.","정답. 概念(がいねん) = 개념","念은 「ねん」. 「にん」은 認·任 등의 음.","念을 「れん」(恋·練)과 혼동한 읽기."],ko: "「자유」라는 개념은 나라에 따라 조금씩 다르다.",ref: ["v:概念"]},
  {id: "kj-003",type: "kanji",q: "その意見には何の〔根拠〕もない。",opts: ["こんこ","ごんきょ","こんきょ","こんきょう"],a: 2,why: ["拠는 요음 「きょ」. 「こ」로 읽으면 틀린다.","根은 청음 「こん」. 탁음화하지 않는다.","정답. 根拠(こんきょ) = 근거","「きょ」는 단음. 장음을 붙이면 틀린다."],ko: "그 의견에는 아무런 근거도 없다.",ref: ["v:根拠"]},
  {id: "kj-004",type: "kanji",q: "まず〔仮説〕を立てて、それを実験で確かめる。",opts: ["けせつ","かぜつ","かせい","かせつ"],a: 3,why: ["仮를 「け」로 읽는 것은 仮病(けびょう) 등 일부 말뿐이다.","説은 청음 「せつ」. 탁음화하지 않는다.","説을 「せい」로 읽는 말(遊説)도 있지만 仮説은 「かせつ」.","정답. 仮説(かせつ) = 가설"],ko: "먼저 가설을 세우고 그것을 실험으로 확인한다.",ref: ["v:仮説"]},
  {id: "kj-005",type: "kanji",q: "一瞬、自分が空を飛んでいるような〔錯覚〕に陥った。",opts: ["さくかく","さっがく","さっかく","しゃっかく"],a: 2,why: ["錯(さく)+覚(かく)는 촉음화해 「さっかく」가 된다.","覚은 청음 「かく」. 탁음이 아니다.","정답. 錯覚(さっかく) = 착각","錯은 직음 「さく」. 요음 「しゃ」가 아니다."],ko: "한순간 자신이 하늘을 날고 있는 듯한 착각에 빠졌다.",ref: ["v:錯覚"]},
  {id: "kj-006",type: "kanji",q: "〔先入観〕にとらわれずに、相手の話を聞くべきだ。",opts: ["せんにゅうかん","せんにゅかん","せんいりかん","せんにゅうがん"],a: 0,why: ["정답. 先入観(せんにゅうかん) = 선입견","入은 장음 「にゅう」. 장음 누락.","入을 훈독 「いり」로 읽은 오답. 한자어이므로 음독.","観은 청음 「かん」. 탁음화하지 않는다."],ko: "선입견에 사로잡히지 말고 상대의 이야기를 들어야 한다.",ref: ["v:先入観"]},
  {id: "kj-007",type: "kanji",q: "外国人に対する〔偏見〕をなくしたい。",opts: ["へんげん","べんけん","へんかん","へんけん"],a: 3,why: ["見은 청음 「けん」. 탁음화하지 않는다.","偏은 청음 「へん」. 탁음이 아니다.","見(けん)을 観·換(かん)과 혼동한 읽기.","정답. 偏見(へんけん) = 편견"],ko: "외국인에 대한 편견을 없애고 싶다.",ref: ["v:偏見"]},
  {id: "kj-008",type: "kanji",q: "彼の話は昨日の説明と〔矛盾〕している。",opts: ["むしゅん","むじゅん","もじゅん","むじゅう"],a: 1,why: ["盾은 탁음 「じゅん」. 청음으로 읽으면 틀린다.","정답. 矛盾(むじゅん) = 모순","矛는 「む」. 「も」로 읽지 않는다.","盾은 「じゅん」. 「じゅう」로 읽지 않는다."],ko: "그의 이야기는 어제 설명과 모순된다.",ref: ["v:矛盾"]},
  {id: "kj-009",type: "kanji",q: "相手の立場も〔考慮〕に入れて判断する必要がある。",opts: ["こうりょう","こうりょ","こうろ","ごうりょ"],a: 1,why: ["慮는 단음 「りょ」. 장음을 붙이면 틀린다.","정답. 考慮(こうりょ) = 고려","慮는 요음 「りょ」. 「ろ」로 읽으면 틀린다.","考는 청음 「こう」. 탁음이 아니다."],ko: "상대의 입장도 고려해 판단할 필요가 있다.",ref: ["v:考慮"]},
  {id: "kj-010",type: "kanji",q: "この駅は車いすの人に〔配慮〕した設計になっている。",opts: ["はいりょう","ばいりょ","はいりょく","はいりょ"],a: 3,why: ["慮는 단음 「りょ」. 장음 추가.","配는 청음 「はい」. 倍(ばい)와 혼동.","慮를 力(りょく)과 혼동한 읽기.","정답. 配慮(はいりょ) = 배려"],ko: "이 역은 휠체어 이용자를 배려한 설계로 되어 있다.",ref: ["v:配慮"]},
  {id: "kj-011",type: "kanji",q: "彼の説明は〔抽象〕的で、よく分からなかった。",opts: ["ちゅうしょう","ちゅうぞう","ゆうしょう","ちゅしょう"],a: 0,why: ["정답. 抽象(ちゅうしょう) = 추상","象을 「ぞう」(코끼리)로 읽은 오답. 抽象에서는 「しょう」.","抽를 由·油(ゆ)와 혼동한 읽기.","抽는 장음 「ちゅう」. 장음 누락."],ko: "그의 설명은 추상적이어서 잘 이해되지 않았다.",ref: ["v:抽象"]},
  {id: "kj-012",type: "kanji",q: "白い鳩は平和の〔象徴〕とされている。",opts: ["ぞうちょう","しょうび","しょうちょう","しょうちょ"],a: 2,why: ["象을 「ぞう」로 읽은 오답. 象徴에서는 「しょう」.","徴(ちょう)를 모양이 비슷한 微(び)와 혼동.","정답. 象徴(しょうちょう) = 상징","徴는 장음 「ちょう」. 장음 누락."],ko: "흰 비둘기는 평화의 상징으로 여겨진다.",ref: ["v:象徴"]},
  {id: "kj-013",type: "kanji",q: "この詩には分かりやすい〔比喩〕がたくさん使われている。",opts: ["ひゅ","ひゆう","びゆ","ひゆ"],a: 3,why: ["比(ひ)+喩(ゆ) 두 음절. 요음으로 합치지 않는다.","喩는 단음 「ゆ」. 장음 추가.","比는 청음 「ひ」. 탁음이 아니다.","정답. 比喩(ひゆ) = 비유"],ko: "이 시에는 알기 쉬운 비유가 많이 쓰이고 있다.",ref: ["v:比喩"]},
  {id: "kj-014",type: "kanji",q: "父は三十年間、橋の建設に〔携わる〕仕事をしてきた。",opts: ["たずさまる","たずねる","たずさわる","けいわる"],a: 2,why: ["「たずさわる」의 わ를 ま로 바꾼 틀린 읽기.","尋ねる(묻다, 찾다)의 읽기. 携わる와는 다른 말.","정답. 携わる(たずさわる) = 종사하다, 관여하다","携의 음독 「けい」에 훈독 어미를 붙인 틀린 읽기."],ko: "아버지는 30년간 다리 건설에 종사하는 일을 해 왔다.",ref: ["v:携わる"]},
  {id: "kj-015",type: "kanji",q: "二つの事件には〔類似〕した点が多い。",opts: ["るいし","るいじ","りゅうじ","らいじ"],a: 1,why: ["似는 탁음 「じ」. 청음으로 읽으면 틀린다.","정답. 類似(るいじ) = 유사","類는 「るい」. 「りゅう」(流·留)와 혼동.","類를 모양이 비슷한 頼(らい)와 혼동."],ko: "두 사건에는 비슷한 점이 많다.",ref: ["v:類似"]},
  {id: "kj-016",type: "kanji",q: "両者の意見には大きな〔相違〕がある。",opts: ["そうい","そい","しょうい","あいい"],a: 0,why: ["정답. 相違(そうい) = 상이, 차이","相은 장음 「そう」. 장음 누락.","相을 首相의 「しょう」로 읽은 오답. 相違에서는 「そう」.","相을 훈독 「あい」로 읽은 오답."],ko: "양측의 의견에는 큰 차이가 있다.",ref: ["v:相違"]},
  {id: "kj-017",type: "kanji",q: "準備を〔怠る〕と、思わぬ失敗をすることになる。",opts: ["なまける","おこたる","おこる","おこだる"],a: 1,why: ["「なまける」는 怠ける로 쓴다. 怠る는 「おこたる」.","정답. 怠る(おこたる) = 게을리하다, 소홀히 하다","怒る(화내다)의 읽기. 의미도 다르다.","「おこたる」의 た는 청음. 탁음화하지 않는다."],ko: "준비를 게을리하면 뜻밖의 실패를 하게 된다.",ref: ["v:怠る"]},
  {id: "kj-018",type: "kanji",q: "彼女には音楽家としての〔素質〕がある。",opts: ["そしつ","すしつ","そじつ","そしち"],a: 0,why: ["정답. 素質(そしつ) = 소질","素를 「す」로 읽는 것은 素顔(すがお) 등. 素質은 「そしつ」.","質은 청음 「しつ」. 탁음화하지 않는다.","質을 「しち」로 읽는 것은 質屋(しちや) 등. 素質에서는 「しつ」."],ko: "그녀에게는 음악가로서의 소질이 있다.",ref: ["v:素質"]},
  {id: "kj-019",type: "kanji",q: "危険から逃げようとするのは動物の〔本能〕だ。",opts: ["ほんの","ぼんのう","ほんどう","ほんのう"],a: 3,why: ["能는 장음 「のう」. 장음 누락(ほんの는 「불과」라는 다른 말).","「ぼんのう」는 煩悩(번뇌)의 읽기. 本은 청음 「ほん」.","能를 「どう」(堂·道)로 읽은 오답.","정답. 本能(ほんのう) = 본능"],ko: "위험에서 도망치려는 것은 동물의 본능이다.",ref: ["v:本能"]},
  {id: "kj-020",type: "kanji",q: "彼は〔典型〕的な仕事人間だ。",opts: ["てんげい","でんけい","てんけい","てんがた"],a: 2,why: ["型은 청음 「けい」. 탁음화하지 않는다.","典은 청음 「てん」. 伝(でん)과 혼동.","정답. 典型(てんけい) = 전형","型을 훈독 「かた」로 읽은 오답. 한자어이므로 음독."],ko: "그는 전형적인 일벌레다.",ref: ["v:典型"]},
  {id: "kj-021",type: "kanji",q: "この素材は〔柔軟性〕に優れていて、曲げても割れない。",opts: ["にゅうなんせい","じゅなんせい","じゅうなんせい","じゅうなんしょう"],a: 2,why: ["柔를 「にゅう」로 읽는 것은 柔和(にゅうわ) 등. 柔軟性은 「じゅう」.","柔는 장음 「じゅう」. 장음 누락.","정답. 柔軟性(じゅうなんせい) = 유연성","性을 「しょう」로 읽는 것은 相性 등. 柔軟性에서는 「せい」."],ko: "이 소재는 유연성이 뛰어나서 구부려도 깨지지 않는다.",ref: ["v:柔軟性"]},
  {id: "kj-022",type: "kanji",q: "専門家に計画の〔妥当性〕を検討してもらった。",opts: ["たとうせい","だとせい","だとうしょう","だとうせい"],a: 3,why: ["妥는 탁음 「だ」. 청음으로 읽으면 틀린다.","当은 장음 「とう」. 장음 누락.","性은 여기서 「せい」. 「しょう」가 아니다.","정답. 妥当性(だとうせい) = 타당성"],ko: "전문가에게 계획의 타당성을 검토받았다.",ref: ["v:妥当性"]},
  {id: "kj-023",type: "kanji",q: "親が子を思う気持ちは、時代を超えた〔普遍〕的なものだ。",opts: ["ふへん","ふべん","ふうへん","ふへい"],a: 0,why: ["정답. 普遍(ふへん) = 보편","遍은 청음 「へん」. 「ふべん」은 不便(불편)의 읽기.","普는 단음 「ふ」. 장음 추가.","遍을 「へい」로 읽은 오답(不平과 혼동)."],ko: "부모가 자식을 생각하는 마음은 시대를 초월한 보편적인 것이다.",ref: ["v:普遍"]},
  {id: "kj-024",type: "kanji",q: "自分の作品を〔客観〕的に見るのは難しい。",opts: ["きゃくかん","きゃっかん","きゃかん","きゃっがん"],a: 1,why: ["客(きゃく)+観(かん)은 촉음화해 「きゃっかん」이 된다.","정답. 客観(きゃっかん) = 객관","촉음 「っ」 누락.","観은 청음 「かん」. 탁음화하지 않는다."],ko: "자신의 작품을 객관적으로 보기는 어렵다.",ref: ["v:客観"]},
  {id: "kj-025",type: "kanji",q: "市は住民に節水を〔促す〕ポスターを駅に貼った。",opts: ["そくす","うなかす","もよおす","うながす"],a: 3,why: ["促의 음독 「そく」에 す를 붙인 틀린 읽기.","「うながす」의 が는 탁음. 청음 누락.","催す(개최하다, 재촉하다)의 읽기. 促す와 다른 말.","정답. 促す(うながす) = 재촉하다, 촉진하다"],ko: "시는 주민에게 절수를 촉구하는 포스터를 역에 붙였다.",ref: ["v:促す"]},
  {id: "kj-026",type: "kanji",q: "社会の〔秩序〕を守るために法律がある。",opts: ["ちつじょう","ちつじょ","ちつしょ","てつじょ"],a: 1,why: ["序는 단음 「じょ」. 장음 추가.","정답. 秩序(ちつじょ) = 질서","序는 탁음 「じょ」. 청음으로 읽으면 틀린다.","秩을 모양이 비슷한 鉄(てつ)와 혼동."],ko: "사회의 질서를 지키기 위해 법률이 있다.",ref: ["v:秩序"]},
  {id: "kj-027",type: "kanji",q: "子どもは大人の行動を見て、社会の〔規範〕を学ぶ。",opts: ["きばん","ぎはん","きはん","きへん"],a: 2,why: ["範은 청음 「はん」. 「きばん」은 基盤(기반)의 읽기.","規는 청음 「き」. 탁음이 아니다.","정답. 規範(きはん) = 규범","範을 「へん」(編·遍)과 혼동한 읽기."],ko: "아이는 어른의 행동을 보고 사회의 규범을 배운다.",ref: ["v:規範"]},
  {id: "kj-028",type: "kanji",q: "彼の勇気ある行動は、多くの人の〔称賛〕を浴びた。",opts: ["しょうさん","しょうざん","しょさん","せいさん"],a: 0,why: ["정답. 称賛(しょうさん) = 칭찬, 찬사","賛은 청음 「さん」. 탁음화하지 않는다.","称은 장음 「しょう」. 장음 누락.","称(しょう)을 모양이 비슷한 精·清(せい)와 혼동."],ko: "그의 용기 있는 행동은 많은 사람의 칭찬을 받았다.",ref: ["v:称賛"]},
  {id: "kj-029",type: "kanji",q: "成績だけが人を測る〔尺度〕ではない。",opts: ["しゃくど","しゃくと","しゃっど","しゃくたく"],a: 0,why: ["정답. 尺度(しゃくど) = 척도","度는 탁음 「ど」. 청음으로 읽으면 틀린다.","尺度는 촉음화하지 않는다.","度를 「たく」로 읽는 것은 支度(したく) 등. 尺度에서는 「ど」."],ko: "성적만이 사람을 재는 척도는 아니다.",ref: ["v:尺度"]},
  {id: "kj-030",type: "kanji",q: "この単語は日常会話での使用〔頻度〕が高い。",opts: ["ひんと","びんど","ひんど","ひんどう"],a: 2,why: ["度는 탁음 「ど」. 청음 「と」가 아니다.","頻은 청음 「ひん」. 탁음이 아니다.","정답. 頻度(ひんど) = 빈도","度는 단음 「ど」. 장음 추가."],ko: "이 단어는 일상 회화에서의 사용 빈도가 높다.",ref: ["v:頻度"]},
  {id: "kj-031",type: "kanji",q: "〔過剰〕な包装は、ごみを増やす原因になる。",opts: ["かじょ","かじょう","かしょう","がじょう"],a: 1,why: ["剰는 장음 「じょう」. 장음 누락.","정답. 過剰(かじょう) = 과잉","剰는 탁음 「じょう」. 청음으로 읽으면 틀린다.","過는 청음 「か」. 탁음이 아니다."],ko: "과잉 포장은 쓰레기를 늘리는 원인이 된다.",ref: ["v:過剰"]},
  {id: "kj-032",type: "kanji",q: "時間に〔余裕〕を持って家を出た。",opts: ["よよう","ようゆう","よゆ","よゆう"],a: 3,why: ["裕는 「ゆう」. 「よう」(容·用)와 혼동.","余는 단음 「よ」. 장음 추가.","裕는 장음 「ゆう」. 장음 누락.","정답. 余裕(よゆう) = 여유"],ko: "시간에 여유를 두고 집을 나섰다.",ref: ["v:余裕"]},
  {id: "kj-033",type: "kanji",q: "夜中の工事の音は、住民の睡眠を〔妨げる〕。",opts: ["さまたげる","さまだげる","さえぎる","ぼうげる"],a: 0,why: ["정답. 妨げる(さまたげる) = 방해하다","「さまたげる」의 た는 청음. 탁음화하지 않는다.","遮る(가로막다)의 읽기. 妨げる와 다른 말.","妨의 음독 「ぼう」에 훈독 어미를 붙인 틀린 읽기."],ko: "한밤중의 공사 소리는 주민의 수면을 방해한다.",ref: ["v:妨げる"]},
  {id: "kj-034",type: "kanji",q: "輸出と輸入の〔均衡〕が崩れている。",opts: ["きんごう","きんこう","きんきょう","ぎんこう"],a: 1,why: ["衡은 청음 「こう」. 탁음화하지 않는다.","정답. 均衡(きんこう) = 균형","衡을 「きょう」로 읽은 오답(均의 영향).","均은 청음 「きん」. 「ぎんこう」는 銀行(은행)의 읽기."],ko: "수출과 수입의 균형이 무너져 있다.",ref: ["v:均衡"]},
  {id: "kj-035",type: "kanji",q: "次の条件に〔該当〕する方は、窓口までお越しください。",opts: ["かいとう","がいどう","がいとう","がいと"],a: 2,why: ["該는 탁음 「がい」. 「かいとう」는 回答·解答의 읽기.","当은 청음 「とう」. 탁음화하지 않는다.","정답. 該当(がいとう) = 해당","当은 장음 「とう」. 장음 누락."],ko: "다음 조건에 해당하는 분은 창구로 와 주십시오.",ref: ["v:該当"]},
  {id: "kj-036",type: "kanji",q: "彼の料理の腕前はプロに〔匹敵〕する。",opts: ["ひつてき","ひきてき","ひってい","ひってき"],a: 3,why: ["匹(ひつ)+敵(てき)은 촉음화해 「ひってき」가 된다.","匹을 훈독 「ひき」(마리)로 읽은 오답.","敵은 「てき」. 「てい」로 읽지 않는다.","정답. 匹敵(ひってき) = 필적"],ko: "그의 요리 솜씨는 프로에 필적한다.",ref: ["v:匹敵"]},
  {id: "kj-037",type: "kanji",q: "日本語と同じ〔系統〕の言語は少ないと言われる。",opts: ["けいどう","けいと","けいとう","けとう"],a: 2,why: ["統은 청음 「とう」. 탁음화하지 않는다.","統은 장음 「とう」. 장음 누락(けいと는 毛糸의 읽기).","정답. 系統(けいとう) = 계통","系는 장음 「けい」. 「け」로 줄이지 않는다."],ko: "일본어와 같은 계통의 언어는 적다고 한다.",ref: ["v:系統"]},
  {id: "kj-038",type: "kanji",q: "時代による服装の〔変遷〕について調べた。",opts: ["へんせん","へんさん","へんせい","べんせん"],a: 0,why: ["정답. 変遷(へんせん) = 변천","遷은 「せん」. 「さん」으로 읽지 않는다.","遷을 「せい」로 읽은 오답(編成·変声과 혼동).","変은 청음 「へん」. 탁음이 아니다."],ko: "시대에 따른 복장의 변천에 대해 조사했다.",ref: ["v:変遷"]},
  {id: "kj-039",type: "kanji",q: "彼はその研究に十年もの時間を〔費やす〕ことになった。",opts: ["ひやす","ついえす","つやす","ついやす"],a: 3,why: ["冷やす(차게 하다)의 읽기. 費의 음 「ひ」에 끌린 오답.","「ついやす」의 や를 え로 바꾼 틀린 읽기.","「つい」의 い가 빠진 틀린 읽기.","정답. 費やす(ついやす) = 소비하다, 쏟다"],ko: "그는 그 연구에 10년이나 되는 시간을 쓰게 되었다.",ref: ["v:費やす"]},
  {id: "kj-040",type: "kanji",q: "若者が減って、地方の産業が〔衰退〕している。",opts: ["すいだい","すいたい","あいたい","すいてい"],a: 1,why: ["退는 청음 「たい」. 탁음화하지 않는다.","정답. 衰退(すいたい) = 쇠퇴","衰를 모양이 비슷한 哀(あい)와 혼동.","退는 「たい」. 「てい」(低·停)와 혼동."],ko: "젊은이가 줄어 지방 산업이 쇠퇴하고 있다.",ref: ["v:衰退"]},
  {id: "kj-041",type: "kanji",q: "不況のため、事業を〔縮小〕することになった。",opts: ["しゅうしょう","しゅくしょう","しゅくしょ","しゅっしょう"],a: 1,why: ["縮은 「しゅく」. 장음 「しゅう」가 아니다.","정답. 縮小(しゅくしょう) = 축소","小는 장음 「しょう」. 장음 누락.","縮小는 촉음화하지 않는다."],ko: "불황 때문에 사업을 축소하게 되었다.",ref: ["v:縮小"]},
  {id: "kj-042",type: "kanji",q: "景気の〔停滞〕が長く続いている。",opts: ["ていだい","てったい","ちょうたい","ていたい"],a: 3,why: ["滞는 청음 「たい」. 탁음화하지 않는다.","「てったい」는 撤退(철퇴)의 읽기. 停은 「てい」.","停은 「てい」. 「ちょう」(頂·庁)로 읽지 않는다.","정답. 停滞(ていたい) = 정체"],ko: "경기 정체가 오래 계속되고 있다.",ref: ["v:停滞"]},
  {id: "kj-043",type: "kanji",q: "病気の小さな〔兆候〕を見逃さないことが大切だ。",opts: ["ちょうこう","ちょうこ","ちょこう","ちょうごう"],a: 0,why: ["정답. 兆候(ちょうこう) = 징후","候는 장음 「こう」. 장음 누락.","兆는 장음 「ちょう」. 장음 누락.","候는 청음 「こう」. 탁음화하지 않는다."],ko: "병의 작은 징후를 놓치지 않는 것이 중요하다.",ref: ["v:兆候"]},
  {id: "kj-044",type: "kanji",q: "留学を〔契機〕に、将来の夢が大きく変わった。",opts: ["けいぎ","ていき","けいき","けき"],a: 2,why: ["機는 청음 「き」. 탁음화하지 않는다.","契를 모양이 비슷한 定·提(てい)와 혼동.","정답. 契機(けいき) = 계기","契는 장음 「けい」. 장음 누락."],ko: "유학을 계기로 장래의 꿈이 크게 바뀌었다.",ref: ["v:契機"]},
  {id: "kj-045",type: "kanji",q: "今は古い制度から新しい制度への〔過渡期〕だ。",opts: ["かどき","かとうき","かとご","かとき"],a: 3,why: ["渡는 청음 「と」. 탁음화하지 않는다.","渡는 단음 「と」. 장음 추가.","期를 「ご」로 읽는 것은 最期(さいご) 등. 過渡期에서는 「き」.","정답. 過渡期(かとき) = 과도기"],ko: "지금은 낡은 제도에서 새 제도로 가는 과도기다.",ref: ["v:過渡期"]},
  {id: "kj-046",type: "kanji",q: "事故に至った〔経緯〕を詳しく説明してください。",opts: ["きょうい","けいき","けいい","けいえい"],a: 2,why: ["経를 経典의 「きょう」로 읽은 오답. 経緯에서는 「けい」.","緯는 「い」. 「き」로 읽지 않는다(けいき는 景気 등의 읽기).","정답. 経緯(けいい) = 경위","緯를 「えい」로 읽은 오답. 「けいえい」는 経営(경영)의 읽기."],ko: "사고에 이르게 된 경위를 자세히 설명해 주세요.",ref: ["v:経緯"]},
  {id: "kj-047",type: "kanji",q: "適度な運動は血液の〔循環〕をよくする。",opts: ["しゅんかん","じゅんかん","じゅんがん","じゅかん"],a: 1,why: ["循은 탁음 「じゅん」. 「しゅんかん」은 瞬間(순간)의 읽기.","정답. 循環(じゅんかん) = 순환","環은 청음 「かん」. 탁음화하지 않는다.","循은 「じゅん」. 「ん」 누락."],ko: "적당한 운동은 혈액 순환을 좋게 한다.",ref: ["v:循環"]},
  {id: "kj-048",type: "kanji",q: "薬の効果がどのくらい〔持続〕するか調べている。",opts: ["じぞく","じそく","ちぞく","じぞう"],a: 0,why: ["정답. 持続(じぞく) = 지속","続은 탁음 「ぞく」. 청음으로 읽으면 틀린다.","持는 「じ」. 「ち」로 읽지 않는다.","続을 「ぞう」로 읽은 오답(じぞう는 地蔵의 읽기)."],ko: "약의 효과가 얼마나 지속되는지 조사하고 있다.",ref: ["v:持続"]},
  {id: "kj-049",type: "kanji",q: "このままでは、地域の伝統行事が〔消滅〕してしまう。",opts: ["しょうめい","しょうめつ","しょめつ","しょうべつ"],a: 1,why: ["滅은 「めつ」. 「しょうめい」는 証明·照明의 읽기.","정답. 消滅(しょうめつ) = 소멸","消는 장음 「しょう」. 장음 누락.","滅을 「べつ」(別)와 혼동한 읽기."],ko: "이대로라면 지역의 전통 행사가 소멸되고 만다.",ref: ["v:消滅"]},
  {id: "kj-050",type: "kanji",q: "この町の名前の〔由来〕を知っていますか。",opts: ["ゆらい","ゆうらい","ゆいらい","ゆだい"],a: 0,why: ["정답. 由来(ゆらい) = 유래","由는 여기서 단음 「ゆ」. 장음 추가(由는 理由에서 「ゆう」).","由를 「ゆい」로 읽는 것은 由緒(ゆいしょ) 등. 由来에서는 「ゆ」.","来는 「らい」. 「だい」로 읽지 않는다."],ko: "이 동네 이름의 유래를 알고 있습니까?",ref: ["v:由来"]},
  {id: "kj-051",type: "kanji",q: "交渉は新たな〔局面〕を迎えた。",opts: ["きょくめい","ぎょくめん","きょうめん","きょくめん"],a: 3,why: ["面은 「めん」. 「めい」로 읽지 않는다.","局은 청음 「きょく」. 「ぎょく」는 玉의 음.","局은 「きょく」. 「く」를 장음으로 바꾼 오답.","정답. 局面(きょくめん) = 국면"],ko: "협상은 새로운 국면을 맞이했다.",ref: ["v:局面"]},
  {id: "kj-052",type: "kanji",q: "この問題は、経済的な〔側面〕からも考える必要がある。",opts: ["そくめい","がわめん","そくめん","ぞくめん"],a: 2,why: ["面은 「めん」. 「めい」로 읽지 않는다.","側을 훈독 「がわ」로 읽은 오답. 한자어이므로 음독.","정답. 側面(そくめん) = 측면","側은 청음 「そく」. 탁음화하지 않는다."],ko: "이 문제는 경제적인 측면에서도 생각할 필요가 있다.",ref: ["v:側面"]},
  {id: "kj-053",type: "kanji",q: "工場からの排水で川が〔汚染〕された。",opts: ["おぜん","おせい","おせん","おうせん"],a: 2,why: ["染은 청음 「せん」. 탁음화하지 않는다(おぜん은 お膳의 읽기).","染을 「せい」로 읽은 오답.","정답. 汚染(おせん) = 오염","汚는 단음 「お」. 장음 추가(おうせん은 応戦의 읽기)."],ko: "공장에서 나온 배수로 강이 오염되었다.",ref: ["v:汚染"]},
  {id: "kj-054",type: "kanji",q: "工場は二酸化炭素の〔排出〕を減らす努力をしている。",opts: ["ばいしゅつ","はいしゅう","はいじゅつ","はいしゅつ"],a: 3,why: ["排는 청음 「はい」. 탁음이 아니다.","出은 「しゅつ」. 「しゅう」(収·集)와 혼동.","出은 청음 「しゅつ」. 탁음화하지 않는다.","정답. 排出(はいしゅつ) = 배출"],ko: "공장은 이산화탄소 배출을 줄이는 노력을 하고 있다.",ref: ["v:排出"]},
  {id: "kj-055",type: "kanji",q: "豊かな自然が、子どもたちの感性を〔育む〕。",opts: ["はぐくむ","そだくむ","はぐぐむ","はごくむ"],a: 0,why: ["정답. 育む(はぐくむ) = 키우다, 기르다","育을 「そだ」로 읽는 것은 育てる・育つ. 育む는 「はぐくむ」.","「はぐくむ」의 두 번째 く는 청음. 탁음화하지 않는다.","「はぐくむ」의 ぐ를 ご로 바꾼 틀린 읽기."],ko: "풍요로운 자연이 아이들의 감성을 길러 준다.",ref: ["v:育む"]},
  {id: "kj-056",type: "kanji",q: "この鳥は〔絶滅〕の危機にある。",opts: ["ぜつめい","ぜつめつ","せつめつ","ぜいめつ"],a: 1,why: ["滅은 「めつ」. 「めい」로 읽지 않는다.","정답. 絶滅(ぜつめつ) = 멸종, 절멸","絶은 탁음 「ぜつ」. 청음으로 읽으면 틀린다.","絶은 「ぜつ」. 「ぜい」(税)와 혼동."],ko: "이 새는 멸종 위기에 있다.",ref: ["v:絶滅"]},
  {id: "kj-057",type: "kanji",q: "大雨で川があふれ、〔洪水〕が起きた。",opts: ["こうすい","こずい","きょうずい","こうずい"],a: 3,why: ["水는 여기서 탁음 「ずい」. 「こうすい」는 香水(향수)의 읽기.","洪은 장음 「こう」. 장음 누락.","洪은 「こう」. 「きょう」로 읽지 않는다.","정답. 洪水(こうずい) = 홍수"],ko: "큰비로 강이 넘쳐 홍수가 일어났다.",ref: ["v:洪水"]},
  {id: "kj-058",type: "kanji",q: "火山が〔噴火〕して、町は灰に覆われた。",opts: ["ふんが","ふんか","ぶんか","ほんか"],a: 1,why: ["火는 청음 「か」. 탁음화하지 않는다.","정답. 噴火(ふんか) = 분화","噴은 청음 「ふん」. 「ぶんか」는 文化(문화)의 읽기.","噴은 「ふん」. 「ほん」으로 읽지 않는다."],ko: "화산이 분화하여 마을은 재로 뒤덮였다.",ref: ["v:噴火"]},
  {id: "kj-059",type: "kanji",q: "地震で〔被災〕した人々を支援する活動に参加した。",opts: ["ひざい","ひせい","ひさい","びさい"],a: 2,why: ["災는 청음 「さい」. 탁음화하지 않는다.","災는 「さい」. 「せい」로 읽지 않는다.","정답. 被災(ひさい) = 재해를 입음, 피재","被는 청음 「ひ」. 「びさい」는 微細의 읽기."],ko: "지진으로 재해를 입은 사람들을 지원하는 활동에 참가했다.",ref: ["v:被災"]},
  {id: "kj-060",type: "kanji",q: "被災地に各国から〔救援〕物資が届いた。",opts: ["きゅうえん","きゅえん","きゅうえい","きゅういん"],a: 0,why: ["정답. 救援(きゅうえん) = 구원, 구호","救는 장음 「きゅう」. 장음 누락.","援은 「えん」. 「えい」로 읽지 않는다.","援을 「いん」(員·院)과 혼동한 읽기."],ko: "피해 지역에 각국에서 구호 물자가 도착했다.",ref: ["v:救援"]},
  {id: "kj-061",type: "kanji",q: "医者に軽い胃炎だと〔診断〕された。",opts: ["しんだん","しんたん","じんだん","しんどん"],a: 0,why: ["정답. 診断(しんだん) = 진단","断은 탁음 「だん」. 청음으로 읽으면 틀린다.","診은 청음 「しん」. 탁음이 아니다.","断은 「だん」. 「どん」으로 읽지 않는다."],ko: "의사에게 가벼운 위염이라고 진단받았다.",ref: ["v:診断"]},
  {id: "kj-062",type: "kanji",q: "疲れがたまると〔免疫〕が下がって、風邪をひきやすくなる。",opts: ["めんやく","めんえい","めんえき","べんえき"],a: 2,why: ["疫을 「やく」로 읽는 것은 疫病神(やくびょうがみ) 등. 免疫에서는 「えき」.","疫은 「えき」. 「えい」로 읽지 않는다.","정답. 免疫(めんえき) = 면역","免은 「めん」. 「べん」(便·勉)과 혼동."],ko: "피로가 쌓이면 면역이 떨어져 감기에 걸리기 쉬워진다.",ref: ["v:免疫"]},
  {id: "kj-063",type: "kanji",q: "犯人は事件のあった日のうちに〔逮捕〕された。",opts: ["たいぼ","たいほ","だいほ","たいほう"],a: 1,why: ["捕는 청음 「ほ」. 탁음화하지 않는다.","정답. 逮捕(たいほ) = 체포","逮는 청음 「たい」. 탁음이 아니다.","捕는 단음 「ほ」. 장음 추가(たいほう는 大砲의 읽기)."],ko: "범인은 사건이 있던 그날 안에 체포되었다.",ref: ["v:逮捕"]},
  {id: "kj-064",type: "kanji",q: "警察が事件の〔捜査〕を進めている。",opts: ["しょうさ","そさ","そうざ","そうさ"],a: 3,why: ["捜는 「そう」. 「しょう」로 읽지 않는다.","捜는 장음 「そう」. 장음 누락.","査는 청음 「さ」. 탁음화하지 않는다.","정답. 捜査(そうさ) = 수사"],ko: "경찰이 사건 수사를 진행하고 있다.",ref: ["v:捜査"]},
  {id: "kj-065",type: "kanji",q: "目撃者の〔証言〕が事件解決の決め手になった。",opts: ["しょうげん","しょうごん","しょうけん","せいげん"],a: 0,why: ["정답. 証言(しょうげん) = 증언","言은 여기서 「げん」. 「ごん」은 伝言(でんごん) 등의 읽기.","言은 탁음 「げん」. 청음으로 읽으면 틀린다(しょうけん은 証券의 읽기).","証을 「せい」로 읽은 오답(せいげん은 制限의 읽기)."],ko: "목격자의 증언이 사건 해결의 결정적 단서가 되었다.",ref: ["v:証言"]},
  {id: "kj-066",type: "kanji",q: "〔過疎〕が進む村では、学校が次々に閉校している。",opts: ["かそう","かそ","かしょ","がそ"],a: 1,why: ["疎는 단음 「そ」. 장음 추가.","정답. 過疎(かそ) = 과소(인구가 지나치게 적음)","疎는 직음 「そ」. 요음 「しょ」가 아니다.","過는 청음 「か」. 탁음이 아니다."],ko: "과소화가 진행되는 마을에서는 학교가 잇달아 문을 닫고 있다.",ref: ["v:過疎"]},
  {id: "kj-067",type: "kanji",q: "子どもが生まれたので、都心から〔郊外〕に引っ越した。",opts: ["こがい","こうかい","こうがい","こうそと"],a: 2,why: ["郊는 장음 「こう」. 장음 누락.","外는 탁음 「がい」. 청음으로 읽으면 틀린다(こうかい는 後悔 등의 읽기).","정답. 郊外(こうがい) = 교외","外를 훈독 「そと」로 읽은 오답."],ko: "아이가 태어나서 도심에서 교외로 이사했다.",ref: ["v:郊外"]},
  {id: "kj-068",type: "kanji",q: "この国は〔治安〕がいいことで知られている。",opts: ["じあん","ちあい","しあん","ちあん"],a: 3,why: ["治를 「じ」로 읽는 것은 政治·退治 등. 治安에서는 「ち」.","安은 「あん」. 「あい」로 읽지 않는다.","治는 「ち」. 「しあん」은 思案·試案의 읽기.","정답. 治安(ちあん) = 치안"],ko: "이 나라는 치안이 좋은 것으로 알려져 있다.",ref: ["v:治安"]},
  {id: "kj-069",type: "kanji",q: "この町の〔世帯〕数は年々減っている。",opts: ["せだい","せおび","せたい","よたい"],a: 2,why: ["帯는 청음 「たい」. 「せだい」는 世代(세대·연령층)의 읽기.","帯를 훈독 「おび」로 읽은 오답.","정답. 世帯(せたい) = 세대, 가구","世를 훈독 「よ」로 읽은 오답. 世帯는 「せ」."],ko: "이 동네의 세대 수는 해마다 줄고 있다.",ref: ["v:世帯"]},
  {id: "kj-070",type: "kanji",q: "国境をめぐる〔紛争〕がいまだに続いている。",opts: ["ふんそう","ぶんそう","ふんしょう","ふんぞう"],a: 0,why: ["정답. 紛争(ふんそう) = 분쟁","紛은 청음 「ふん」. 탁음이 아니다.","争은 「そう」. 「しょう」로 읽지 않는다.","争은 청음 「そう」. 탁음화하지 않는다."],ko: "국경을 둘러싼 분쟁이 아직도 계속되고 있다.",ref: ["v:紛争"]},
  {id: "kj-071",type: "kanji",q: "戦争によって多くの〔難民〕が生まれた。",opts: ["なんにん","なんめい","なみん","なんみん"],a: 3,why: ["民은 「みん」. 「にん」(人)으로 읽지 않는다.","民은 「みん」. 「めい」(名·明)와 혼동.","難은 「なん」. 「ん」 누락.","정답. 難民(なんみん) = 난민"],ko: "전쟁으로 많은 난민이 생겼다.",ref: ["v:難民"]},
  {id: "kj-072",type: "kanji",q: "高いビルが建って、町の〔景観〕が損なわれた。",opts: ["けいがん","けいかん","きょうかん","けかん"],a: 1,why: ["観은 청음 「かん」. 탁음화하지 않는다.","정답. 景観(けいかん) = 경관","景은 「けい」. 「きょう」(共·京)와 혼동.","景은 장음 「けい」. 장음 누락."],ko: "높은 빌딩이 들어서서 동네의 경관이 훼손되었다.",ref: ["v:景観"]},
  {id: "kj-073",type: "kanji",q: "新しい工場は地域に多くの〔雇用〕を生み出した。",opts: ["こうよう","こよう","こよ","ごよう"],a: 1,why: ["雇는 단음 「こ」. 장음 추가(こうよう는 紅葉 등의 읽기).","정답. 雇用(こよう) = 고용","用은 장음 「よう」. 장음 누락.","雇는 청음 「こ」. 「ごよう」는 御用의 읽기."],ko: "새 공장은 지역에 많은 고용을 만들어 냈다.",ref: ["v:雇用"]},
  {id: "kj-074",type: "kanji",q: "業績の悪化で、多くの社員が〔解雇〕された。",opts: ["かいご","げこ","かいこう","かいこ"],a: 3,why: ["雇는 청음 「こ」. 「かいご」는 介護(간병)의 읽기.","解를 「げ」로 읽는 것은 解熱·解毒 등. 解雇는 「かい」.","雇는 단음 「こ」. 장음 추가.","정답. 解雇(かいこ) = 해고"],ko: "실적 악화로 많은 사원이 해고되었다.",ref: ["v:解雇"]},
  {id: "kj-075",type: "kanji",q: "〔顧客〕の個人情報は厳しく管理されている。",opts: ["こきゃく","こかく","こうきゃく","こっきゃく"],a: 0,why: ["정답. 顧客(こきゃく) = 고객","客은 「きゃく」. 「かく」로 읽지 않는다.","顧는 단음 「こ」. 장음 추가.","顧客은 촉음화하지 않는다."],ko: "고객의 개인 정보는 엄격하게 관리되고 있다.",ref: ["v:顧客"]},
  {id: "kj-076",type: "kanji",q: "修理が終わった後で、高い料金を〔請求〕された。",opts: ["せいきゅ","しょうきゅう","せいきゅう","じょうきゅう"],a: 2,why: ["求는 장음 「きゅう」. 장음 누락.","請을 「しょう」로 읽는 것은 普請 등. 請求에서는 「せい」.","정답. 請求(せいきゅう) = 청구","請은 「せい」. 「じょうきゅう」는 上級의 읽기."],ko: "수리가 끝난 뒤 비싼 요금을 청구받았다.",ref: ["v:請求"]},
  {id: "kj-077",type: "kanji",q: "ご注文の商品は来週〔納品〕する予定です。",opts: ["のうしな","なっぴん","のひん","のうひん"],a: 3,why: ["品을 훈독 「しな」로 읽은 오답.","納을 「なっ」으로 읽는 것은 納得(なっとく) 등. 納品은 「のう」.","納은 장음 「のう」. 장음 누락.","정답. 納品(のうひん) = 납품"],ko: "주문하신 상품은 다음 주에 납품할 예정입니다.",ref: ["v:納品"]},
  {id: "kj-078",type: "kanji",q: "申し訳ありませんが、その商品は〔在庫〕を切らしております。",opts: ["さいこ","ざいご","ざいこ","ざいく"],a: 2,why: ["在는 탁음 「ざい」. 청음으로 읽으면 틀린다(さいこ는 最古의 읽기).","庫는 청음 「こ」. 탁음화하지 않는다.","정답. 在庫(ざいこ) = 재고","庫를 「く」로 읽는 것은 庫裏 등 일부 말뿐. 在庫는 「こ」."],ko: "죄송합니다만, 그 상품은 재고가 떨어졌습니다.",ref: ["v:在庫"]},
  {id: "kj-079",type: "kanji",q: "この工場では、毎朝トラックで野菜を〔出荷〕している。",opts: ["しゅつか","しゅっか","しゅっが","しゅつに"],a: 1,why: ["出(しゅつ)+荷(か)는 촉음화해 「しゅっか」가 된다.","정답. 出荷(しゅっか) = 출하","荷는 청음 「か」. 탁음화하지 않는다.","荷를 훈독 「に」로 읽은 오답."],ko: "이 공장에서는 매일 아침 트럭으로 채소를 출하하고 있다.",ref: ["v:出荷"]},
  {id: "kj-080",type: "kanji",q: "四月から営業の〔部署〕で働いている。",opts: ["ぶしょ","ぶしょう","ふしょ","ぶじょ"],a: 0,why: ["정답. 部署(ぶしょ) = 부서","署는 단음 「しょ」. 장음 추가(ぶしょう는 無精의 읽기).","部는 탁음 「ぶ」. 청음으로 읽으면 틀린다.","署는 청음 「しょ」. 탁음화하지 않는다."],ko: "4월부터 영업 부서에서 일하고 있다.",ref: ["v:部署"]},
  {id: "kj-081",type: "kanji",q: "新しい販売〔戦略〕を立てる必要がある。",opts: ["せんりょく","せんりゃく","せんらく","ぜんりゃく"],a: 1,why: ["略은 「りゃく」. 「せんりょく」는 戦力(전력)의 읽기.","정답. 戦略(せんりゃく) = 전략","略은 요음 「りゃく」. 직음 「らく」가 아니다.","戦은 청음 「せん」. 「ぜんりゃく」는 前略의 읽기."],ko: "새로운 판매 전략을 세울 필요가 있다.",ref: ["v:戦略"]},
  {id: "kj-082",type: "kanji",q: "新製品のおかげで、会社の〔業績〕が回復してきた。",opts: ["ぎょうせき","ごうせき","ぎょせき","ぎょうしゃく"],a: 0,why: ["정답. 業績(ぎょうせき) = 업적, 실적","業을 「ごう」로 읽는 것은 自業自得 등. 業績에서는 「ぎょう」.","業은 장음 「ぎょう」. 장음 누락.","績은 「せき」. 「しゃく」로 읽지 않는다."],ko: "신제품 덕분에 회사 실적이 회복되었다.",ref: ["v:業績"]},
  {id: "kj-083",type: "kanji",q: "仕事に見合った〔報酬〕を受け取るのは当然だ。",opts: ["ほうしゅ","ほうじゅう","ほうしょう","ほうしゅう"],a: 3,why: ["酬는 장음 「しゅう」. 장음 누락.","酬는 청음 「しゅう」. 탁음화하지 않는다.","酬는 「しゅう」. 「ほうしょう」는 報償·褒賞의 읽기.","정답. 報酬(ほうしゅう) = 보수"],ko: "일에 걸맞은 보수를 받는 것은 당연하다.",ref: ["v:報酬"]},
  {id: "kj-084",type: "kanji",q: "この会社は社員の〔待遇〕がいいことで有名だ。",opts: ["だいぐう","たいぐ","たいぐう","たいごう"],a: 2,why: ["待는 청음 「たい」. 탁음이 아니다.","遇는 장음 「ぐう」. 장음 누락.","정답. 待遇(たいぐう) = 대우","遇는 「ぐう」. 「ごう」로 읽지 않는다."],ko: "이 회사는 사원 대우가 좋기로 유명하다.",ref: ["v:待遇"]},
  {id: "kj-085",type: "kanji",q: "風邪をひいて、三日間会社を〔欠勤〕した。",opts: ["けつきん","けっぎん","けっきん","けつごん"],a: 2,why: ["欠(けつ)+勤(きん)은 촉음화해 「けっきん」이 된다.","勤은 청음 「きん」. 탁음화하지 않는다.","정답. 欠勤(けっきん) = 결근","勤을 「ごん」으로 읽는 것은 勤行(ごんぎょう) 등. 欠勤에서는 「きん」."],ko: "감기에 걸려 3일간 회사를 결근했다.",ref: ["v:欠勤"]},
  {id: "kj-086",type: "kanji",q: "この会社では〔賞与〕が年に二回支給される。",opts: ["しょうよう","しょよ","じょうよ","しょうよ"],a: 3,why: ["与는 단음 「よ」. 장음 추가.","賞은 장음 「しょう」. 장음 누락.","賞은 청음 「しょう」. 「じょうよ」는 剰余(잉여)의 읽기.","정답. 賞与(しょうよ) = 상여금, 보너스"],ko: "이 회사에서는 상여금이 1년에 두 번 지급된다.",ref: ["v:賞与"]},
  {id: "kj-087",type: "kanji",q: "雨のため、試合は来週に〔延期〕された。",opts: ["えんき","えんぎ","えんご","いんき"],a: 0,why: ["정답. 延期(えんき) = 연기","期는 청음 「き」. 「えんぎ」는 演技·縁起의 읽기.","期를 「ご」로 읽는 것은 最期 등. 延期에서는 「き」(えんご는 援護의 읽기).","延은 「えん」. 「いん」으로 읽지 않는다."],ko: "비 때문에 시합은 다음 주로 연기되었다.",ref: ["v:延期"]},
  {id: "kj-088",type: "kanji",q: "ビザの〔申請〕に必要な書類をそろえた。",opts: ["しんぜい","しんせい","しんしょう","もうせい"],a: 1,why: ["請은 청음 「せい」. 탁음화하지 않는다.","정답. 申請(しんせい) = 신청","請을 「しょう」로 읽은 오답. 申請에서는 「せい」.","申을 훈독 「もう(す)」로 읽은 오답."],ko: "비자 신청에 필요한 서류를 갖추었다.",ref: ["v:申請"]},
  {id: "kj-089",type: "kanji",q: "こちらの書類に〔印鑑〕を押してください。",opts: ["いんがん","いんけん","いっかん","いんかん"],a: 3,why: ["鑑은 청음 「かん」. 탁음화하지 않는다.","鑑은 「かん」. 「けん」(券·検)과 혼동.","印鑑은 촉음화하지 않는다(いっかん은 一環·一貫의 읽기).","정답. 印鑑(いんかん) = 인감, 도장"],ko: "이쪽 서류에 도장을 찍어 주세요.",ref: ["v:印鑑"]},
  {id: "kj-090",type: "kanji",q: "双方が少しずつ〔譲歩〕して、ようやく合意に達した。",opts: ["じょうぶ","じょうほ","じょほ","しょうほ"],a: 1,why: ["歩는 청음 「ほ」. 「じょうぶ」는 丈夫(튼튼함)의 읽기.","정답. 譲歩(じょうほ) = 양보","譲은 장음 「じょう」. 장음 누락.","譲은 탁음 「じょう」. 청음으로 읽으면 틀린다."],ko: "양측이 조금씩 양보해서 겨우 합의에 이르렀다.",ref: ["v:譲歩"]},
  {id: "kj-091",type: "kanji",q: "品質の面では一切〔妥協〕したくない。",opts: ["たきょう","だきょ","だきょう","だごう"],a: 2,why: ["妥는 탁음 「だ」. 청음으로 읽으면 틀린다.","協은 장음 「きょう」. 장음 누락.","정답. 妥協(だきょう) = 타협","協은 「きょう」. 「ごう」(合)와 혼동."],ko: "품질 면에서는 일절 타협하고 싶지 않다.",ref: ["v:妥協"]},
  {id: "kj-092",type: "kanji",q: "友人に手紙の翻訳を〔依頼〕した。",opts: ["いらい","えらい","いれい","いだい"],a: 0,why: ["정답. 依頼(いらい) = 의뢰","依를 「え」로 읽는 것은 帰依(きえ) 등. 依頼는 「い」.","頼는 「らい」. 「れい」(例·礼)와 혼동.","頼는 「らい」. 「いだい」는 偉大의 읽기."],ko: "친구에게 편지 번역을 의뢰했다.",ref: ["v:依頼"]},
  {id: "kj-093",type: "kanji",q: "大学では経済学を〔専攻〕していた。",opts: ["せんこう","せんこ","せんごう","ぜんこう"],a: 0,why: ["정답. 専攻(せんこう) = 전공","攻은 장음 「こう」. 장음 누락.","攻은 청음 「こう」. 탁음화하지 않는다.","専은 청음 「せん」. 「ぜんこう」는 善行의 읽기."],ko: "대학에서는 경제학을 전공했다.",ref: ["v:専攻"]},
  {id: "kj-094",type: "kanji",q: "卒業に必要な科目をすべて〔履修〕した。",opts: ["りしゅ","りじゅう","りしゅう","りしゅく"],a: 2,why: ["修는 장음 「しゅう」. 장음 누락.","修는 청음 「しゅう」. 탁음화하지 않는다.","정답. 履修(りしゅう) = 이수","修는 「しゅう」. 「しゅく」(宿·縮)와 혼동."],ko: "졸업에 필요한 과목을 모두 이수했다.",ref: ["v:履修"]},
  {id: "kj-095",type: "kanji",q: "〔奨学金〕をもらいながら大学に通っている。",opts: ["しょがくきん","しょうがくきん","しょうかくきん","そうがくきん"],a: 1,why: ["奨은 장음 「しょう」. 장음 누락.","정답. 奨学金(しょうがくきん) = 장학금","学은 여기서 탁음 「がく」. 청음으로 읽으면 틀린다.","奨은 요음 「しょう」. 직음 「そう」가 아니다."],ko: "장학금을 받으면서 대학에 다니고 있다.",ref: ["v:奨学金"]},
  {id: "kj-096",type: "kanji",q: "論文を書くために、多くの〔文献〕を読んだ。",opts: ["ぶんこん","もんけん","ぶんげん","ぶんけん"],a: 3,why: ["献은 여기서 「けん」. 「こん」은 献立(こんだて)의 읽기.","文을 「もん」으로 읽는 것은 文句 등. 文献에서는 「ぶん」.","献은 청음 「けん」. 탁음화하지 않는다.","정답. 文献(ぶんけん) = 문헌"],ko: "논문을 쓰기 위해 많은 문헌을 읽었다.",ref: ["v:文献"]},
  {id: "kj-097",type: "kanji",q: "彼は銀行員から作家になった、珍しい〔経歴〕の持ち主だ。",opts: ["けいれき","きょうれき","けいりゃく","けいれい"],a: 0,why: ["정답. 経歴(けいれき) = 경력, 이력","経를 経典의 「きょう」로 읽은 오답. 経歴에서는 「けい」.","歴은 「れき」. 「りゃく」(略)와 혼동.","歴은 「れき」. 「れい」로 읽지 않는다(けいれい는 敬礼의 읽기)."],ko: "그는 은행원에서 작가가 된 드문 경력의 소유자다.",ref: ["v:経歴"]},
  {id: "kj-098",type: "kanji",q: "町の歴史を〔遡る〕と、意外な事実が見えてくる。",opts: ["さかのぼす","さかのぼる","さがのぼる","さかもどる"],a: 1,why: ["어미는 「る」. 「さかのぼす」라는 말은 없다.","정답. 遡る(さかのぼる) = 거슬러 올라가다, 소급하다","「さかのぼる」의 か는 청음. 탁음화하지 않는다.","「戻る(もどる)」와 혼동한 틀린 읽기."],ko: "마을의 역사를 거슬러 올라가면 뜻밖의 사실이 보인다.",ref: ["v:遡る"]},
  {id: "kj-099",type: "kanji",q: "不況で取引先の会社が〔倒産〕した。",opts: ["どうさん","とさん","とうさん","とうざん"],a: 2,why: ["倒는 청음 「とう」. 탁음이 아니다.","倒는 장음 「とう」. 장음 누락.","정답. 倒産(とうさん) = 도산","産은 청음 「さん」. 탁음화하지 않는다."],ko: "불황으로 거래처 회사가 도산했다.",ref: ["v:倒産"]},
  {id: "kj-100",type: "kanji",q: "父は来月から海外に〔赴任〕することになった。",opts: ["ふじん","ぶにん","ほにん","ふにん"],a: 3,why: ["任은 「にん」. 「ふじん」은 婦人·夫人의 읽기.","赴는 청음 「ふ」. 탁음이 아니다.","赴는 「ふ」. 「ほ」로 읽지 않는다.","정답. 赴任(ふにん) = 부임"],ko: "아버지는 다음 달부터 해외에 부임하게 되었다.",ref: ["v:赴任"]},
  {id: "kj-101",type: "kanji",q: "会議の前に関係者に〔根回し〕をしておいた。",opts: ["こんまわし","ねまわり","ねまわし","ねかえし"],a: 2,why: ["根을 음독 「こん」으로 읽은 오답. 根回し는 훈독 「ね」.","回し는 「まわし」. 「まわり」(回り)가 아니다.","정답. 根回し(ねまわし) = 사전 조율","回し를 「かえし」(返し)와 혼동한 읽기."],ko: "회의 전에 관계자들에게 사전 조율을 해 두었다.",ref: ["v:根回し"]},
  {id: "kj-102",type: "kanji",q: "作業を始める前に、〔段取り〕をしっかり確認しよう。",opts: ["だんどり","たんどり","だんとり","だんしゅ"],a: 0,why: ["정답. 段取り(だんどり) = (일의) 순서, 준비","段은 탁음 「だん」. 청음으로 읽으면 틀린다.","取り는 연탁해 「どり」가 된다.","取り를 음독 「しゅ」로 읽은 오답."],ko: "작업을 시작하기 전에 순서를 확실히 확인하자.",ref: ["v:段取り"]},
  {id: "kj-103",type: "kanji",q: "将来に備えて、毎月の生活費を〔倹約〕している。",opts: ["げんやく","けいやく","けんよく","けんやく"],a: 3,why: ["倹은 청음 「けん」. 탁음이 아니다.","倹은 「けん」. 「けいやく」는 契約(계약)의 읽기.","約은 「やく」. 「よく」(浴·欲)와 혼동.","정답. 倹約(けんやく) = 검약, 절약"],ko: "장래에 대비해 매달 생활비를 절약하고 있다.",ref: ["v:倹約"]},
  {id: "kj-104",type: "kanji",q: "冷蔵庫の中を見ながら、今夜の〔献立〕を考える。",opts: ["けんだて","こんだて","こんたて","けんりつ"],a: 1,why: ["献을 「けん」으로 읽는 것은 文献 등. 献立에서는 「こん」.","정답. 献立(こんだて) = 식단, 메뉴","立는 연탁해 「だて」가 된다.","立을 음독 「りつ」로 읽은 오답(けんりつ는 県立의 읽기)."],ko: "냉장고 안을 보면서 오늘 저녁 식단을 생각한다.",ref: ["v:献立"]},
  {id: "kj-105",type: "kanji",q: "出かける前に〔戸締まり〕を確認した。",opts: ["こじまり","とじまり","とうじまり","とじまい"],a: 1,why: ["戸를 음독 「こ」로 읽은 오답. 戸締まり는 훈독 「と」.","정답. 戸締まり(とじまり) = 문단속","戸는 단음 「と」. 장음 추가.","締まり는 「じまり」. 「じまい」(仕舞い)와 혼동."],ko: "외출하기 전에 문단속을 확인했다.",ref: ["v:戸締まり"]},
  {id: "kj-106",type: "kanji",q: "梅雨の時期は部屋の〔湿気〕が多くて困る。",opts: ["しつけ","しっけい","しっげ","しっけ"],a: 3,why: ["湿(しつ)+気(け)는 촉음화해 「しっけ」가 된다(しつけ는 躾(예의범절)의 읽기).","気는 여기서 단음 「け」. 「しっけい」는 失敬의 읽기.","気는 청음 「け」. 탁음화하지 않는다.","정답. 湿気(しっけ) = 습기"],ko: "장마철에는 방의 습기가 많아서 곤란하다.",ref: ["v:湿気"]},
  {id: "kj-107",type: "kanji",q: "冬に備えて、リスは木の実を〔蓄える〕。",opts: ["たくわえる","たくえる","たくらえる","そなえる"],a: 0,why: ["정답. 蓄える(たくわえる) = 비축하다, 저축하다","「たくわえる」의 わ가 빠진 틀린 읽기.","「たくわえる」의 わ를 ら로 바꾼 틀린 읽기.","備える(대비하다)의 읽기. 蓄える와 다른 말."],ko: "겨울에 대비해 다람쥐는 나무 열매를 모아 둔다.",ref: ["v:蓄える"]},
  {id: "kj-108",type: "kanji",q: "足りない栄養はサプリメントで〔補う〕つもりだ。",opts: ["おごなう","おこなう","おぎなう","つくろう"],a: 2,why: ["「おぎなう」의 ぎ를 ご로 바꾼 틀린 읽기.","行う(행하다)의 읽기. 補う와 다른 말.","정답. 補う(おぎなう) = 보충하다, 메우다","繕う(수선하다)의 읽기. 補う와 다른 말."],ko: "부족한 영양은 보충제로 보충할 생각이다.",ref: ["v:補う"]},
  {id: "kj-109",type: "kanji",q: "食事中の〔行儀〕が悪いと、母に注意された。",opts: ["こうぎ","ぎょぎ","ぎょうき","ぎょうぎ"],a: 3,why: ["行을 「こう」로 읽은 오답. 「こうぎ」는 講義·抗議의 읽기.","行은 장음 「ぎょう」. 장음 누락.","儀는 탁음 「ぎ」. 청음으로 읽으면 틀린다.","정답. 行儀(ぎょうぎ) = 예의범절, 행동거지"],ko: "식사 중 예절이 나쁘다고 어머니에게 주의를 받았다.",ref: ["v:行儀"]},
  {id: "kj-110",type: "kanji",q: "〔遠慮〕しないで、たくさん食べてくださいね。",opts: ["えんりょう","おんりょ","えんりょ","えんろ"],a: 2,why: ["慮는 단음 「りょ」. 장음 추가.","遠을 「おん」으로 읽는 것은 久遠(くおん) 등. 遠慮에서는 「えん」.","정답. 遠慮(えんりょ) = 사양, 삼감","慮는 요음 「りょ」. 직음 「ろ」가 아니다."],ko: "사양하지 말고 많이 드세요.",ref: ["v:遠慮"]},
  {id: "kj-111",type: "kanji",q: "説明が足りなくて、相手の〔誤解〕を招いてしまった。",opts: ["こかい","ごかい","ごけい","ごがい"],a: 1,why: ["誤는 탁음 「ご」. 청음으로 읽으면 틀린다.","정답. 誤解(ごかい) = 오해","解는 「かい」. 「けい」로 읽지 않는다.","解는 청음 「かい」. 탁음화하지 않는다."],ko: "설명이 부족해서 상대의 오해를 사고 말았다.",ref: ["v:誤解"]},
  {id: "kj-112",type: "kanji",q: "人の〔陰口〕を言うのはよくない。",opts: ["かげぐち","かげくち","いんぐち","いんこう"],a: 0,why: ["정답. 陰口(かげぐち) = 뒷담화","口는 연탁해 「ぐち」가 된다.","陰을 음독 「いん」으로 읽은 오답. 陰口는 훈독 「かげ」.","陰口는 훈독 말. 음독 「いんこう」로 읽지 않는다."],ko: "남의 험담을 하는 것은 좋지 않다.",ref: ["v:陰口"]},
  {id: "kj-113",type: "kanji",q: "友人の成功に、つい〔嫉妬〕してしまった。",opts: ["しつと","しっと","しっとう","じっと"],a: 1,why: ["嫉(しつ)+妬(と)는 촉음화해 「しっと」가 된다.","정답. 嫉妬(しっと) = 질투","妬는 단음 「と」. 장음 추가.","嫉은 청음 「しっ」. 「じっと」는 「가만히」라는 부사."],ko: "친구의 성공에 그만 질투를 하고 말았다.",ref: ["v:嫉妬"]},
  {id: "kj-114",type: "kanji",q: "優秀な兄に対して、ずっと〔劣等感〕を抱いていた。",opts: ["れっとうかん","れつとうかん","れっとかん","れっどうかん"],a: 0,why: ["정답. 劣等感(れっとうかん) = 열등감","劣(れつ)+等(とう)은 촉음화해 「れっとう」가 된다.","等은 장음 「とう」. 장음 누락.","等은 청음 「とう」. 탁음화하지 않는다."],ko: "우수한 형에게 줄곧 열등감을 품고 있었다.",ref: ["v:劣等感"]},
  {id: "kj-115",type: "kanji",q: "突然の質問に、〔戸惑い〕を隠せなかった。",opts: ["こまどい","とまよい","とわく","とまどい"],a: 3,why: ["戸를 음독 「こ」로 읽은 오답. 戸惑い는 「と」.","惑い를 「まよい」(迷い)와 혼동한 읽기.","惑을 음독 「わく」로 읽은 오답.","정답. 戸惑い(とまどい) = 당혹, 망설임"],ko: "갑작스러운 질문에 당혹감을 감추지 못했다.",ref: ["v:戸惑い"]},
  {id: "kj-116",type: "kanji",q: "試験が近づくにつれて、〔焦り〕を感じるようになった。",opts: ["こげり","しょうり","あせり","あさり"],a: 2,why: ["焦를 焦げる(こげる)의 「こげ」로 읽은 오답.","焦를 음독 「しょう」로 읽은 오답(しょうり는 勝利의 읽기).","정답. 焦り(あせり) = 초조함, 조바심","「あせり」의 せ를 さ로 바꾼 오답(あさり는 바지락)."],ko: "시험이 다가올수록 초조함을 느끼게 되었다.",ref: ["v:焦り"]},
  {id: "kj-117",type: "kanji",q: "彼は自分の仕事に〔誇り〕を持っている。",opts: ["ほごり","ほまれ","ほこり","こり"],a: 2,why: ["「ほこり」의 こ는 청음. 탁음화하지 않는다.","誉れ(명예)의 읽기. 誇り와 다른 말.","정답. 誇り(ほこり) = 자랑, 긍지","誇를 음독 「こ」로 읽은 오답(こり는 凝り의 읽기)."],ko: "그는 자신의 일에 자부심을 가지고 있다.",ref: ["v:誇り"]},
  {id: "kj-118",type: "kanji",q: "彼はお酒を飲むと、いつも仕事の〔愚痴〕ばかり言う。",opts: ["ぐうち","ぐじ","くち","ぐち"],a: 3,why: ["愚는 단음 「ぐ」. 장음 추가.","痴는 「ち」. 「じ」로 읽지 않는다.","愚는 탁음 「ぐ」. 「くち」는 口의 읽기.","정답. 愚痴(ぐち) = 푸념, 넋두리"],ko: "그는 술을 마시면 늘 일에 대한 푸념만 늘어놓는다.",ref: ["v:愚痴"]},
  {id: "kj-119",type: "kanji",q: "夜中に、廊下で誰かの〔気配〕を感じた。",opts: ["けはい","けいはい","けばい","きくばり"],a: 0,why: ["정답. 気配(けはい) = 기척, 기미","気는 여기서 단음 「け」. 장음 추가.","配는 청음 「はい」. 탁음화하지 않는다.","「きくばり」는 気配り(배려)의 읽기. 気配와 다른 말."],ko: "한밤중에 복도에서 누군가의 기척을 느꼈다.",ref: ["v:気配"]},
  {id: "kj-120",type: "kanji",q: "この電池の〔寿命〕は約五年だと言われている。",opts: ["じゅめい","じゅみょう","じゅうみょう","じゅみょ"],a: 1,why: ["命은 여기서 「みょう」. 「めい」로 읽지 않는다.","정답. 寿命(じゅみょう) = 수명","寿는 단음 「じゅ」. 장음 추가.","命은 장음 「みょう」. 장음 누락."],ko: "이 전지의 수명은 약 5년이라고 한다.",ref: ["v:寿命"]},
  {id: "hy-001",type: "hyoki",q: "安全の〔かんてん〕から、計画をもう一度見直す。",opts: ["観点","勧点","観展","歓点"],a: 0,why: ["정답. 観点(かんてん) = 관점","勧(권할 권)은 観(볼 관)과 음이 같은 다른 한자.","展(펼 전)은 「てん」이지만 관점의 点(점)이 아니다.","歓(기쁠 환)은 観과 모양·음이 비슷한 다른 한자."],ko: "안전의 관점에서 계획을 다시 한번 재검토한다.",ref: ["v:観点"]},
  {id: "hy-002",type: "hyoki",q: "全員が参加することを〔ぜんてい〕に、計画を立てた。",opts: ["前程","前提","全提","前堤"],a: 1,why: ["程(정도 정)은 「てい」이지만 前提의 提(끌 제)가 아니다.","정답. 前提(ぜんてい) = 전제","全(온전할 전)은 「ぜん」이지만 前(앞 전)이 맞다.","堤(둑 제)는 提와 모양이 비슷한 다른 한자."],ko: "전원이 참가하는 것을 전제로 계획을 세웠다.",ref: ["v:前提"]},
  {id: "hy-003",type: "hyoki",q: "彼の表情から、結果がよくなかったと〔すいそく〕した。",opts: ["推側","推則","推測","椎測"],a: 2,why: ["側(곁 측)은 測(헤아릴 측)과 모양·음이 비슷한 다른 한자.","則(법칙 칙)은 測과 모양이 비슷한 다른 한자.","정답. 推測(すいそく) = 추측","椎(쇠뭉치 추)는 推(밀 추)와 모양이 비슷한 다른 한자."],ko: "그의 표정으로 결과가 좋지 않았다고 추측했다.",ref: ["v:推測"]},
  {id: "hy-004",type: "hyoki",q: "問題の深刻さを〔にんしき〕していない人が多い。",opts: ["認織","忍識","認職","認識"],a: 3,why: ["織(짤 직)은 識(알 식)과 모양이 비슷한 다른 한자.","忍(참을 인)은 認(알 인)과 음·모양이 비슷한 다른 한자.","職(직분 직)은 識과 모양이 비슷한 다른 한자.","정답. 認識(にんしき) = 인식"],ko: "문제의 심각성을 인식하지 못하는 사람이 많다.",ref: ["v:認識"]},
  {id: "hy-005",type: "hyoki",q: "子どもの自由な〔はっそう〕には、いつも驚かされる。",opts: ["発相","撥想","発想","発創"],a: 2,why: ["相(서로 상)은 「そう」이지만 想(생각 상)이 맞다.","撥(다스릴 발)은 発과 음이 같은 다른 한자.","정답. 発想(はっそう) = 발상","創(비롯할 창)은 「そう」이지만 의미가 다르다."],ko: "아이의 자유로운 발상에는 늘 놀라게 된다.",ref: ["v:発想"]},
  {id: "hy-006",type: "hyoki",q: "地震が起きた場合を〔そうてい〕して、避難訓練を行う。",opts: ["想定","相定","想程","想停"],a: 0,why: ["정답. 想定(そうてい) = 상정, 가정함","相(서로 상)은 想(생각 상)과 음·모양이 비슷한 다른 한자.","程(정도 정)은 「てい」이지만 定(정할 정)이 맞다.","停(머무를 정)은 「てい」이지만 의미가 다르다."],ko: "지진이 일어난 경우를 상정해 피난 훈련을 한다.",ref: ["v:想定"]},
  {id: "hy-007",type: "hyoki",q: "この問題については、専門家の間でも〔けんかい〕が分かれている。",opts: ["見介","険解","見界","見解"],a: 3,why: ["介(낄 개)는 「かい」이지만 解(풀 해)가 맞다.","険(험할 험)은 「けん」이지만 見(볼 견)이 맞다.","界(지경 계)는 「かい」이지만 의미가 다르다.","정답. 見解(けんかい) = 견해"],ko: "이 문제에 대해서는 전문가 사이에서도 견해가 갈린다.",ref: ["v:見解"]},
  {id: "hy-008",type: "hyoki",q: "彼は最後まで自分の無実を〔しゅちょう〕した。",opts: ["主帳","主張","主脹","主長"],a: 1,why: ["帳(장막 장)은 張(베풀 장)과 모양·음이 비슷한 다른 한자.","정답. 主張(しゅちょう) = 주장","脹(부을 창)은 張과 모양이 비슷한 다른 한자.","長(길 장)은 「ちょう」이지만 의미가 다르다."],ko: "그는 끝까지 자신의 무죄를 주장했다.",ref: ["v:主張"]},
  {id: "hy-009",type: "hyoki",q: "警察は犯行の〔どうき〕をまだ明らかにしていない。",opts: ["働機","動機","動期","動器"],a: 1,why: ["働(일할 동)은 動(움직일 동)과 모양이 비슷한 다른 한자.","정답. 動機(どうき) = 동기","期(기약할 기)는 「き」이지만 機(틀 기)가 맞다.","器(그릇 기)는 「き」이지만 의미가 다르다."],ko: "경찰은 범행 동기를 아직 밝히지 않았다.",ref: ["v:動機"]},
  {id: "hy-010",type: "hyoki",q: "彼の質問は、問題の〔ほんしつ〕を鋭く突いていた。",opts: ["本室","本執","本湿","本質"],a: 3,why: ["室(방 실)은 「しつ」이지만 質(바탕 질)이 맞다.","執(잡을 집)은 「しつ」로도 읽지만 의미가 다르다.","湿(젖을 습)은 「しつ」이지만 의미가 다르다.","정답. 本質(ほんしつ) = 본질"],ko: "그의 질문은 문제의 본질을 날카롭게 찌르고 있었다.",ref: ["v:本質"]},
  {id: "hy-011",type: "hyoki",q: "運も成功の大切な〔ようそ〕の一つだ。",opts: ["要素","要租","用素","要索"],a: 0,why: ["정답. 要素(ようそ) = 요소","租(조세 조)는 「そ」이지만 素(본디 소)가 맞다.","用(쓸 용)은 「よう」이지만 要(요긴할 요)가 맞다.","索(찾을 색)은 素와 모양이 비슷한 다른 한자."],ko: "운도 성공의 중요한 요소 중 하나다.",ref: ["v:要素"]},
  {id: "hy-012",type: "hyoki",q: "彼女の説明は〔ろんり〕がはっきりしていて分かりやすい。",opts: ["輪理","論里","論理","論利"],a: 2,why: ["輪(바퀴 륜)은 論(논할 론)과 모양이 비슷한 다른 한자.","里(마을 리)는 「り」이지만 理(다스릴 리)가 맞다.","정답. 論理(ろんり) = 논리","利(이로울 리)는 「り」이지만 의미가 다르다."],ko: "그녀의 설명은 논리가 명확해서 알기 쉽다.",ref: ["v:論理"]},
  {id: "hy-013",type: "hyoki",q: "三時間話し合ったが、〔けつろん〕は出なかった。",opts: ["決論","結輪","欠論","結論"],a: 3,why: ["決(결단할 결)은 「けつ」이지만 結(맺을 결)이 맞다.","輪(바퀴 륜)은 論과 모양이 비슷한 다른 한자.","欠(이지러질 결)은 「けつ」이지만 의미가 다르다.","정답. 結論(けつろん) = 결론"],ko: "세 시간 논의했지만 결론은 나지 않았다.",ref: ["v:結論"]},
  {id: "hy-014",type: "hyoki",q: "集めたデータを〔ぶんせき〕して、報告書にまとめる。",opts: ["分折","分拆","分析","文析"],a: 2,why: ["折(꺾을 절)은 析(쪼갤 석)과 모양이 비슷한 다른 한자.","拆(터질 탁)은 析과 모양이 비슷한 다른 한자.","정답. 分析(ぶんせき) = 분석","文(글월 문)은 「ぶん」이지만 分(나눌 분)이 맞다."],ko: "모은 데이터를 분석해서 보고서로 정리한다.",ref: ["v:分析"]},
  {id: "hy-015",type: "hyoki",q: "実験によって、仮説を〔けんしょう〕する。",opts: ["険証","検証","検訂","剣証"],a: 1,why: ["険(험할 험)은 検(검사할 검)과 모양·음이 비슷한 다른 한자.","정답. 検証(けんしょう) = 검증","訂(바로잡을 정)은 証(증거 증)과 모양이 비슷한 다른 한자.","剣(칼 검)은 検과 모양·음이 비슷한 다른 한자."],ko: "실험을 통해 가설을 검증한다.",ref: ["v:検証"]},
  {id: "hy-016",type: "hyoki",q: "最近は健康を〔いしき〕して、野菜を多く食べるようにしている。",opts: ["意識","意織","意職","異識"],a: 0,why: ["정답. 意識(いしき) = 의식","織(짤 직)은 識(알 식)과 모양이 비슷한 다른 한자.","職(직분 직)은 識과 모양이 비슷한 다른 한자.","異(다를 이)는 「い」이지만 意(뜻 의)가 맞다."],ko: "요즘은 건강을 의식해서 채소를 많이 먹으려 하고 있다.",ref: ["v:意識"]},
  {id: "hy-017",type: "hyoki",q: "彼にはリーダーとしての〔じかく〕が足りない。",opts: ["自角","自覚","字覚","自確"],a: 1,why: ["角(뿔 각)은 「かく」이지만 覚(깨달을 각)이 맞다.","정답. 自覚(じかく) = 자각","字(글자 자)는 「じ」이지만 自(스스로 자)가 맞다.","確(굳을 확)은 「かく」이지만 의미가 다르다."],ko: "그에게는 리더로서의 자각이 부족하다.",ref: ["v:自覚"]},
  {id: "hy-018",type: "hyoki",q: "地震がいつ起きるかを〔よそく〕するのは難しい。",opts: ["予測","予側","余測","予則"],a: 0,why: ["정답. 予測(よそく) = 예측","側(곁 측)은 測(헤아릴 측)과 모양·음이 비슷한 다른 한자.","余(남을 여)는 「よ」이지만 予(미리 예)가 맞다.","則(법칙 칙)은 測과 모양이 비슷한 다른 한자."],ko: "지진이 언제 일어날지를 예측하기는 어렵다.",ref: ["v:予測"]},
  {id: "hy-019",type: "hyoki",q: "社長が会社の将来の〔てんぼう〕について語った。",opts: ["展忘","転望","展亡","展望"],a: 3,why: ["忘(잊을 망)은 「ぼう」이지만 望(바랄 망)이 맞다.","転(구를 전)은 「てん」이지만 展(펼 전)이 맞다.","亡(망할 망)은 「ぼう」이지만 의미가 다르다.","정답. 展望(てんぼう) = 전망"],ko: "사장이 회사의 장래 전망에 대해 이야기했다.",ref: ["v:展望"]},
  {id: "hy-020",type: "hyoki",q: "議論を始める前に、言葉の〔ていぎ〕をはっきりさせよう。",opts: ["定議","低義","定義","定儀"],a: 2,why: ["議(의논할 의)는 「ぎ」이지만 義(옳을 의)가 맞다.","低(낮을 저)는 「てい」이지만 定(정할 정)이 맞다.","정답. 定義(ていぎ) = 정의(뜻을 정함)","儀(거동 의)는 義와 모양·음이 비슷한 다른 한자."],ko: "논의를 시작하기 전에 말의 정의를 분명히 하자.",ref: ["v:定義"]},
  {id: "hy-021",type: "hyoki",q: "最近、若者の読書離れの〔けいこう〕が見られる。",opts: ["頃向","傾行","傾向","経向"],a: 2,why: ["頃(잠깐 경)은 傾(기울 경)에서 亻이 빠진 다른 한자.","行(다닐 행)은 「こう」이지만 向(향할 향)이 맞다.","정답. 傾向(けいこう) = 경향","経(지날 경)은 「けい」이지만 傾이 맞다."],ko: "최근 젊은이들이 책을 멀리하는 경향이 보인다.",ref: ["v:傾向"]},
  {id: "hy-022",type: "hyoki",q: "この掃除機は値段は高いが、〔せいのう〕がいい。",opts: ["生能","性態","姓能","性能"],a: 3,why: ["生(날 생)은 「せい」이지만 性(성품 성)이 맞다.","態(모습 태)는 能(능할 능)과 모양이 비슷한 다른 한자.","姓(성씨 성)은 性과 모양·음이 비슷한 다른 한자.","정답. 性能(せいのう) = 성능"],ko: "이 청소기는 값은 비싸지만 성능이 좋다.",ref: ["v:性能"]},
  {id: "hy-023",type: "hyoki",q: "駅で〔ぐうぜん〕、昔の友人に会った。",opts: ["偶然","遇然","隅然","偶前"],a: 0,why: ["정답. 偶然(ぐうぜん) = 우연","遇(만날 우)는 偶(짝 우)와 모양·음이 비슷한 다른 한자.","隅(모퉁이 우)는 偶와 모양이 비슷한 다른 한자.","前(앞 전)은 「ぜん」이지만 然(그럴 연)이 맞다."],ko: "역에서 우연히 옛 친구를 만났다.",ref: ["v:偶然"]},
  {id: "hy-024",type: "hyoki",q: "この会社は〔どくじ〕の技術で新しい製品を開発した。",opts: ["独持","独自","読自","毒自"],a: 1,why: ["持(가질 지)는 「じ」이지만 自(스스로 자)가 맞다.","정답. 独自(どくじ) = 독자(적), 고유","読(읽을 독)은 「どく」이지만 独(홀로 독)이 맞다.","毒(독 독)은 「どく」이지만 의미가 다르다."],ko: "이 회사는 독자적인 기술로 새 제품을 개발했다.",ref: ["v:独自"]},
  {id: "hy-025",type: "hyoki",q: "彼はどんなに批判されても〔しんねん〕を曲げなかった。",opts: ["伸念","信稔","信捻","信念"],a: 3,why: ["伸(펼 신)은 信(믿을 신)과 모양·음이 비슷한 다른 한자.","稔(곡식 익을 임)은 念(생각 념)과 모양이 비슷한 다른 한자.","捻(비틀 념)은 念과 모양이 비슷한 다른 한자.","정답. 信念(しんねん) = 신념"],ko: "그는 아무리 비판받아도 신념을 굽히지 않았다.",ref: ["v:信念"]},
  {id: "hy-026",type: "hyoki",q: "彼女の作品は海外で高く〔ひょうか〕された。",opts: ["標価","評価","評課","評可"],a: 1,why: ["標(표할 표)는 「ひょう」이지만 評(평할 평)이 맞다.","정답. 評価(ひょうか) = 평가","課(매길 과)는 「か」이지만 価(값 가)가 맞다.","可(옳을 가)는 「か」이지만 의미가 다르다."],ko: "그녀의 작품은 해외에서 높이 평가받았다.",ref: ["v:評価"]},
  {id: "hy-027",type: "hyoki",q: "新しい車のブレーキに〔けっかん〕が見つかった。",opts: ["欠管","決陥","欠陥","欠完"],a: 2,why: ["管(대롱 관)은 「かん」이지만 陥(빠질 함)이 맞다.","決(결단할 결)은 「けつ」이지만 欠(이지러질 결)이 맞다.","정답. 欠陥(けっかん) = 결함","完(완전할 완)은 「かん」이지만 의미가 정반대다."],ko: "새 차의 브레이크에서 결함이 발견되었다.",ref: ["v:欠陥"]},
  {id: "hy-028",type: "hyoki",q: "この町の〔みりょく〕は、何といっても古い町並みだ。",opts: ["魅力","味力","魅緑","未力"],a: 0,why: ["정답. 魅力(みりょく) = 매력","味(맛 미)는 「み」이지만 魅(매혹할 매)가 맞다.","緑(푸를 록)은 「りょく」이지만 力(힘 력)이 맞다.","未(아닐 미)는 「み」이지만 의미가 다르다."],ko: "이 동네의 매력은 뭐니 뭐니 해도 오래된 거리 풍경이다.",ref: ["v:魅力"]},
  {id: "hy-029",type: "hyoki",q: "政府の方針を〔ひはん〕する声が高まっている。",opts: ["批判","比判","批半","批販"],a: 0,why: ["정답. 批判(ひはん) = 비판","比(견줄 비)는 批(비평할 비)와 모양·음이 비슷한 다른 한자.","半(반 반)은 判(판단할 판)의 일부와 모양이 비슷한 다른 한자.","販(팔 판)은 「はん」이지만 의미가 다르다."],ko: "정부 방침을 비판하는 목소리가 높아지고 있다.",ref: ["v:批判"]},
  {id: "hy-030",type: "hyoki",q: "この国の教育の〔すいじゅん〕は非常に高い。",opts: ["水順","水純","水準","推準"],a: 2,why: ["順(순할 순)은 「じゅん」이지만 準(준할 준)이 맞다.","純(순수할 순)은 「じゅん」이지만 의미가 다르다.","정답. 水準(すいじゅん) = 수준","推(밀 추)는 「すい」이지만 水(물 수)가 맞다."],ko: "이 나라의 교육 수준은 매우 높다.",ref: ["v:水準"]},
  {id: "hy-031",type: "hyoki",q: "新しい建物は、安全の〔きじゅん〕を満たしていなかった。",opts: ["基順","基準","基潤","期準"],a: 1,why: ["順(순할 순)은 「じゅん」이지만 準(준할 준)이 맞다.","정답. 基準(きじゅん) = 기준","潤(윤택할 윤)은 「じゅん」이지만 의미가 다르다.","期(기약할 기)는 基(터 기)와 모양·음이 비슷한 다른 한자."],ko: "새 건물은 안전 기준을 충족하지 못했다.",ref: ["v:基準"]},
  {id: "hy-032",type: "hyoki",q: "もう体力の〔げんかい〕で、これ以上は走れない。",opts: ["限階","現界","限介","限界"],a: 3,why: ["階(섬돌 계)는 「かい」이지만 界(지경 계)가 맞다.","現(나타날 현)은 「げん」이지만 限(한할 한)이 맞다.","介(낄 개)는 界와 모양·음이 비슷한 다른 한자.","정답. 限界(げんかい) = 한계"],ko: "이제 체력의 한계라서 더 이상은 못 달린다.",ref: ["v:限界"]},
  {id: "hy-033",type: "hyoki",q: "今回の工事は、予想以上に〔きぼ〕が大きい。",opts: ["規模","規漠","既模","規膜"],a: 0,why: ["정답. 規模(きぼ) = 규모","漠(넓을 막)은 模(본뜰 모)와 모양이 비슷한 다른 한자.","既(이미 기)는 「き」이지만 規(법 규)가 맞다.","膜(막 막)은 模와 모양이 비슷한 다른 한자."],ko: "이번 공사는 예상 이상으로 규모가 크다.",ref: ["v:規模"]},
  {id: "hy-034",type: "hyoki",q: "この学校は男女の〔ひりつ〕がほぼ同じだ。",opts: ["比律","比率","比卒","批率"],a: 1,why: ["律(법칙 률)은 「りつ」이지만 率(비율 률)이 맞다.","정답. 比率(ひりつ) = 비율","卒(마칠 졸)은 率과 모양이 비슷한 다른 한자.","批(비평할 비)는 比(견줄 비)와 모양·음이 비슷한 다른 한자."],ko: "이 학교는 남녀 비율이 거의 같다.",ref: ["v:比率"]},
  {id: "hy-035",type: "hyoki",q: "彼の意見はいつも〔きょくたん〕で、周りを困らせる。",opts: ["局端","曲端","極端","極担"],a: 2,why: ["局(판 국)은 「きょく」이지만 極(다할 극)이 맞다.","曲(굽을 곡)은 「きょく」이지만 極(다할 극)이 맞다.","정답. 極端(きょくたん) = 극단","担(멜 담)은 「たん」이지만 의미가 다르다."],ko: "그의 의견은 늘 극단적이어서 주위를 곤란하게 한다.",ref: ["v:極端"]},
  {id: "hy-036",type: "hyoki",q: "不足している栄養を、サプリメントで〔おぎなう〕。",opts: ["捕う","浦う","哺う","補う"],a: 3,why: ["捕(잡을 포)는 補(기울 보)와 모양이 비슷한 다른 한자.","浦(개 포)는 補와 모양이 비슷한 다른 한자.","哺(먹일 포)는 補와 모양이 비슷한 다른 한자.","정답. 補う(おぎなう) = 보충하다, 메우다"],ko: "부족한 영양을 보충제로 보충한다.",ref: ["v:補う"]},
  {id: "hy-037",type: "hyoki",q: "この事件に〔かんれん〕する記事を集めている。",opts: ["関練","間連","関連","関蓮"],a: 2,why: ["練(익힐 련)은 「れん」이지만 連(잇닿을 련)이 맞다.","間(사이 간)은 関(관계할 관)과 모양·음이 비슷한 다른 한자.","정답. 関連(かんれん) = 관련","蓮(연꽃 련)은 連과 모양이 비슷한 다른 한자."],ko: "이 사건에 관련된 기사를 모으고 있다.",ref: ["v:関連"]},
  {id: "hy-038",type: "hyoki",q: "最近、スマートフォンに〔いぞん〕する若者が増えている。",opts: ["依存","衣存","依損","依尊"],a: 0,why: ["정답. 依存(いぞん) = 의존","衣(옷 의)는 依(의지할 의)의 일부와 모양·음이 같은 다른 한자.","損(덜 손)은 「そん」이지만 存(있을 존)이 맞다.","尊(높을 존)은 「そん」이지만 의미가 다르다."],ko: "최근 스마트폰에 의존하는 젊은이가 늘고 있다.",ref: ["v:依存"]},
  {id: "hy-039",type: "hyoki",q: "開発をめぐって、住民と市の意見が〔たいりつ〕している。",opts: ["対律","体立","対率","対立"],a: 3,why: ["律(법칙 률)은 「りつ」이지만 立(설 립)이 맞다.","体(몸 체)는 「たい」이지만 対(대할 대)가 맞다.","率(비율 률)은 「りつ」이지만 의미가 다르다.","정답. 対立(たいりつ) = 대립"],ko: "개발을 둘러싸고 주민과 시의 의견이 대립하고 있다.",ref: ["v:対立"]},
  {id: "hy-040",type: "hyoki",q: "この建物は周りの自然とよく〔ちょうわ〕している。",opts: ["調話","調和","帳和","潮和"],a: 1,why: ["話(말씀 화)는 「わ」이지만 和(화할 화)가 맞다.","정답. 調和(ちょうわ) = 조화","帳(장막 장)은 「ちょう」이지만 調(고를 조)가 맞다.","潮(조수 조)는 「ちょう」이지만 의미가 다르다."],ko: "이 건물은 주변 자연과 잘 조화를 이루고 있다.",ref: ["v:調和"]},
  {id: "hy-041",type: "hyoki",q: "この小説は、戦争の時代を〔はいけい〕にしている。",opts: ["背軽","背景","拝景","背係"],a: 1,why: ["軽(가벼울 경)은 「けい」이지만 景(볕 경)이 맞다.","정답. 背景(はいけい) = 배경","拝(절 배)는 「はい」이지만 背(등 배)가 맞다.","係(맬 계)는 「けい」이지만 의미가 다르다."],ko: "이 소설은 전쟁 시대를 배경으로 하고 있다.",ref: ["v:背景"]},
  {id: "hy-042",type: "hyoki",q: "何よりも乗客の安全を〔ゆうせん〕しなければならない。",opts: ["優選","憂先","優洗","優先"],a: 3,why: ["選(가릴 선)은 「せん」이지만 先(먼저 선)이 맞다.","憂(근심 우)는 優(넉넉할 우)에서 亻이 빠진 다른 한자.","洗(씻을 세)는 「せん」이지만 의미가 다르다.","정답. 優先(ゆうせん) = 우선"],ko: "무엇보다도 승객의 안전을 우선해야 한다.",ref: ["v:優先"]},
  {id: "hy-043",type: "hyoki",q: "この建物は地震に強い〔こうぞう〕になっている。",opts: ["構造","講造","構像","構増"],a: 0,why: ["정답. 構造(こうぞう) = 구조","講(강론할 강)은 構(얽을 구)와 모양·음이 비슷한 다른 한자.","像(모양 상)은 「ぞう」이지만 造(지을 조)가 맞다.","増(더할 증)은 「ぞう」이지만 의미가 다르다."],ko: "이 건물은 지진에 강한 구조로 되어 있다.",ref: ["v:構造"]},
  {id: "hy-044",type: "hyoki",q: "この教室では、〔げんそく〕として携帯電話の使用は禁止だ。",opts: ["原側","元則","原則","源則"],a: 2,why: ["側(곁 측)은 則(법칙 칙)과 모양이 비슷한 다른 한자.","元(으뜸 원)은 「げん」이지만 原(근원 원)이 맞다.","정답. 原則(げんそく) = 원칙","源(근원 원)은 原에 氵가 붙은 다른 한자."],ko: "이 교실에서는 원칙적으로 휴대 전화 사용이 금지다.",ref: ["v:原則"]},
  {id: "hy-045",type: "hyoki",q: "この町は鉄道の開通とともに大きく〔はってん〕した。",opts: ["発転","発典","撥展","発展"],a: 3,why: ["転(구를 전)은 「てん」이지만 展(펼 전)이 맞다.","典(법 전)은 「てん」이지만 의미가 다르다.","撥(다스릴 발)은 発과 음이 같은 다른 한자.","정답. 発展(はってん) = 발전"],ko: "이 동네는 철도 개통과 함께 크게 발전했다.",ref: ["v:発展"]},
  {id: "hy-046",type: "hyoki",q: "練習を続けたおかげで、技術が〔こうじょう〕した。",opts: ["向乗","高上","向上","向状"],a: 2,why: ["乗(탈 승)은 「じょう」이지만 上(윗 상)이 맞다.","高(높을 고)는 「こう」이지만 向(향할 향)이 맞다.","정답. 向上(こうじょう) = 향상","状(형상 상)은 「じょう」이지만 의미가 다르다."],ko: "연습을 계속한 덕분에 기술이 향상되었다.",ref: ["v:向上"]},
  {id: "hy-047",type: "hyoki",q: "外国人観光客の数が年々〔ぞうか〕している。",opts: ["増可","増加","贈加","憎加"],a: 1,why: ["可(옳을 가)는 「か」이지만 加(더할 가)가 맞다.","정답. 増加(ぞうか) = 증가","贈(줄 증)은 増(더할 증)과 모양·음이 비슷한 다른 한자.","憎(미워할 증)은 増과 모양·음이 비슷한 다른 한자."],ko: "외국인 관광객 수가 해마다 증가하고 있다.",ref: ["v:増加"]},
  {id: "hy-048",type: "hyoki",q: "この村の人口は〔げんしょう〕し続けている。",opts: ["減少","減小","滅少","現少"],a: 0,why: ["정답. 減少(げんしょう) = 감소","小(작을 소)는 「しょう」이지만 少(적을 소)가 맞다.","滅(멸할 멸)은 減(덜 감)과 모양이 비슷한 다른 한자.","現(나타날 현)은 「げん」이지만 減이 맞다."],ko: "이 마을의 인구는 계속 감소하고 있다.",ref: ["v:減少"]},
  {id: "hy-049",type: "hyoki",q: "台風による被害は、さらに〔かくだい〕するおそれがある。",opts: ["鉱大","拡大","拡代","確大"],a: 1,why: ["鉱(쇳돌 광)은 拡(넓힐 확)과 모양이 비슷한 다른 한자.","정답. 拡大(かくだい) = 확대","代(대신할 대)는 「だい」이지만 大(큰 대)가 맞다.","確(굳을 확)은 「かく」이지만 拡가 맞다."],ko: "태풍에 의한 피해는 더욱 확대될 우려가 있다.",ref: ["v:拡大"]},
  {id: "hy-050",type: "hyoki",q: "今年の夏は、気温が四十度近くまで〔じょうしょう〕した。",opts: ["上昇","上晶","上勝","乗昇"],a: 0,why: ["정답. 上昇(じょうしょう) = 상승","晶(맑을 정)은 「しょう」이지만 昇(오를 승)이 맞다.","勝(이길 승)은 「しょう」이지만 의미가 다르다.","乗(탈 승)은 「じょう」이지만 上(윗 상)이 맞다."],ko: "올여름은 기온이 40도 가까이까지 상승했다.",ref: ["v:上昇"]},
  {id: "hy-051",type: "hyoki",q: "生活習慣を〔かいぜん〕して、体調がよくなった。",opts: ["改繕","解善","改然","改善"],a: 3,why: ["繕(기울 선)은 善(착할 선)에 糸가 붙은 다른 한자.","解(풀 해)는 「かい」이지만 改(고칠 개)가 맞다.","然(그럴 연)은 「ぜん」이지만 의미가 다르다.","정답. 改善(かいぜん) = 개선"],ko: "생활 습관을 개선해서 몸 상태가 좋아졌다.",ref: ["v:改善"]},
  {id: "hy-052",type: "hyoki",q: "毎日少しずつでも〔けいぞく〕することが大切だ。",opts: ["継読","係続","継続","継属"],a: 2,why: ["読(읽을 독)은 続(이을 속)과 모양이 비슷한 다른 한자.","係(맬 계)는 「けい」이지만 継(이을 계)가 맞다.","정답. 継続(けいぞく) = 계속, 지속","属(무리 속)은 「ぞく」이지만 의미가 다르다."],ko: "매일 조금씩이라도 계속하는 것이 중요하다.",ref: ["v:継続"]},
  {id: "hy-053",type: "hyoki",q: "健康を〔いじ〕するために、毎朝散歩している。",opts: ["唯持","維待","維持","違持"],a: 2,why: ["唯(오직 유)는 維(벼리 유)와 모양이 비슷한 다른 한자.","待(기다릴 대)는 持(가질 지)와 모양이 비슷한 다른 한자.","정답. 維持(いじ) = 유지","違(어긋날 위)는 「い」이지만 의미가 다르다."],ko: "건강을 유지하기 위해 매일 아침 산책하고 있다.",ref: ["v:維持"]},
  {id: "hy-054",type: "hyoki",q: "数十年ぶりに、町の伝統的な祭りが〔ふっかつ〕した。",opts: ["複活","腹活","復括","復活"],a: 3,why: ["複(겹칠 복)은 復(회복할 복)과 모양·음이 비슷한 다른 한자.","腹(배 복)은 復과 모양·음이 비슷한 다른 한자.","括(묶을 괄)은 活(살 활)과 모양이 비슷한 다른 한자.","정답. 復活(ふっかつ) = 부활"],ko: "수십 년 만에 마을의 전통 축제가 부활했다.",ref: ["v:復活"]},
  {id: "hy-055",type: "hyoki",q: "人類の言語の〔きげん〕については、さまざまな説がある。",opts: ["起源","期源","起限","記源"],a: 0,why: ["정답. 起源(きげん) = 기원","期(기약할 기)는 「き」이지만 起(일어날 기)가 맞다.","限(한할 한)은 「げん」이지만 源(근원 원)이 맞다.","記(기록할 기)는 起와 모양·음이 비슷한 다른 한자."],ko: "인류 언어의 기원에 대해서는 여러 설이 있다.",ref: ["v:起源"]},
  {id: "hy-056",type: "hyoki",q: "毎日の努力の〔せいか〕が、ようやく表れてきた。",opts: ["成課","成果","製果","成菓"],a: 1,why: ["課(매길 과)는 「か」이지만 果(실과 과)가 맞다.","정답. 成果(せいか) = 성과","製(지을 제)는 「せい」이지만 成(이룰 성)이 맞다.","菓(과자 과)는 果에 艹가 붙은 다른 한자."],ko: "매일의 노력의 성과가 겨우 나타나기 시작했다.",ref: ["v:成果"]},
  {id: "hy-057",type: "hyoki",q: "仕事の〔こうりつ〕を上げるために、やり方を見直した。",opts: ["効律","校率","功率","効率"],a: 3,why: ["律(법칙 률)은 「りつ」이지만 率(비율 률)이 맞다.","校(학교 교)는 効(본받을 효)와 모양·음이 비슷한 다른 한자.","功(공 공)은 「こう」이지만 効가 맞다.","정답. 効率(こうりつ) = 효율"],ko: "일의 효율을 올리기 위해 방식을 재검토했다.",ref: ["v:効率"]},
  {id: "hy-058",type: "hyoki",q: "今の給料には満足しているが、〔げんじょう〕のままでいいとは思わない。",opts: ["現常","現状","現情","減状"],a: 1,why: ["常(항상 상)은 「じょう」이지만 状(형상 상)이 맞다.","정답. 現状(げんじょう) = 현상, 현재 상태","情(뜻 정)은 「じょう」이지만 의미가 다르다.","減(덜 감)은 「げん」이지만 現(나타날 현)이 맞다."],ko: "지금 월급에는 만족하지만 현재 상태로 괜찮다고는 생각하지 않는다.",ref: ["v:現状"]},
  {id: "hy-059",type: "hyoki",q: "政府は新しい経済〔せいさく〕を発表した。",opts: ["政作","正策","政策","政索"],a: 2,why: ["作(지을 작)은 「さく」이지만 策(꾀 책)이 맞다.","正(바를 정)은 「せい」이지만 政(정사 정)이 맞다.","정답. 政策(せいさく) = 정책","索(찾을 색)은 「さく」이지만 의미가 다르다."],ko: "정부는 새로운 경제 정책을 발표했다.",ref: ["v:政策"]},
  {id: "hy-060",type: "hyoki",q: "来月、市長の〔せんきょ〕が行われる。",opts: ["選挙","選拠","選居","洗挙"],a: 0,why: ["정답. 選挙(せんきょ) = 선거","拠(근거 거)는 「きょ」이지만 挙(들 거)가 맞다.","居(살 거)는 「きょ」이지만 의미가 다르다.","洗(씻을 세)는 「せん」이지만 選(가릴 선)이 맞다."],ko: "다음 달 시장 선거가 실시된다.",ref: ["v:選挙"]},
  {id: "hy-061",type: "hyoki",q: "日曜日に〔とうひょう〕に行くつもりだ。",opts: ["投票","投標","頭票","投表"],a: 0,why: ["정답. 投票(とうひょう) = 투표","標(표할 표)는 票(표 표)에 木이 붙은 다른 한자.","頭(머리 두)는 「とう」이지만 投(던질 투)가 맞다.","表(겉 표)는 「ひょう」이지만 의미가 다르다."],ko: "일요일에 투표하러 갈 생각이다.",ref: ["v:投票"]},
  {id: "hy-062",type: "hyoki",q: "誰にでも教育を受ける〔けんり〕がある。",opts: ["権理","勧利","権利","検利"],a: 2,why: ["理(다스릴 리)는 「り」이지만 利(이로울 리)가 맞다.","勧(권할 권)은 権(권세 권)과 모양·음이 비슷한 다른 한자.","정답. 権利(けんり) = 권리","検(검사할 검)은 「けん」이지만 의미가 다르다."],ko: "누구에게나 교육을 받을 권리가 있다.",ref: ["v:権利"]},
  {id: "hy-063",type: "hyoki",q: "国民には税金を納める〔ぎむ〕がある。",opts: ["議務","義務","義霧","犠務"],a: 1,why: ["議(의논할 의)는 義(옳을 의)에 言이 붙은 다른 한자.","정답. 義務(ぎむ) = 의무","霧(안개 무)는 務(힘쓸 무)에 雨가 붙은 다른 한자.","犠(희생 희)는 義와 모양이 비슷한 다른 한자."],ko: "국민에게는 세금을 낼 의무가 있다.",ref: ["v:義務"]},
  {id: "hy-064",type: "hyoki",q: "首相は〔がいこう〕問題についての考えを述べた。",opts: ["外効","外校","害交","外交"],a: 3,why: ["効(본받을 효)는 「こう」이지만 交(사귈 교)가 맞다.","校(학교 교)는 交에 木이 붙은 다른 한자.","害(해할 해)는 「がい」이지만 外(바깥 외)가 맞다.","정답. 外交(がいこう) = 외교"],ko: "총리는 외교 문제에 대한 생각을 밝혔다.",ref: ["v:外交"]},
  {id: "hy-065",type: "hyoki",q: "悩みを一人で〔かかえる〕必要はない。誰かに相談してほしい。",opts: ["抱える","包える","泡える","砲える"],a: 0,why: ["정답. 抱える(かかえる) = (팔에) 안다, (문제를) 떠안다","包(쌀 포)는 抱(안을 포)에서 扌가 빠진 다른 한자.","泡(거품 포)는 抱와 모양이 비슷한 다른 한자.","砲(대포 포)는 抱와 모양이 비슷한 다른 한자."],ko: "고민을 혼자 떠안을 필요는 없다. 누군가에게 상담했으면 한다.",ref: ["v:抱える"]},
  {id: "hy-066",type: "hyoki",q: "この国は主に自動車を〔ゆしゅつ〕している。",opts: ["輪出","輸出","諭出","愉出"],a: 1,why: ["輪(바퀴 륜)은 輸(보낼 수)와 모양이 비슷한 다른 한자.","정답. 輸出(ゆしゅつ) = 수출","諭(타이를 유)는 輸와 모양·음이 비슷한 다른 한자.","愉(즐거울 유)는 輸와 모양·음이 비슷한 다른 한자."],ko: "이 나라는 주로 자동차를 수출하고 있다.",ref: ["v:輸出"]},
  {id: "hy-067",type: "hyoki",q: "日本は多くの国と〔ぼうえき〕をしている。",opts: ["貿益","暴易","貿易","貿役"],a: 2,why: ["益(더할 익)은 「えき」이지만 易(바꿀 역)이 맞다.","暴(사나울 폭)은 「ぼう」이지만 貿(무역할 무)가 맞다.","정답. 貿易(ぼうえき) = 무역","役(부릴 역)은 「えき」로도 읽지만 의미가 다르다."],ko: "일본은 많은 나라와 무역을 하고 있다.",ref: ["v:貿易"]},
  {id: "hy-068",type: "hyoki",q: "夏はエアコンの〔じゅよう〕が増える。",opts: ["儒要","需容","授要","需要"],a: 3,why: ["儒(선비 유)는 需(쓰일 수)에 亻이 붙은 다른 한자.","容(얼굴 용)은 「よう」이지만 要(요긴할 요)가 맞다.","授(줄 수)는 「じゅ」이지만 의미가 다르다.","정답. 需要(じゅよう) = 수요"],ko: "여름에는 에어컨 수요가 늘어난다.",ref: ["v:需要"]},
  {id: "hy-069",type: "hyoki",q: "台風の影響で、電力の〔きょうきゅう〕が止まった。",opts: ["共給","供級","供給","協給"],a: 2,why: ["共(함께 공)은 供(이바지할 공)에서 亻이 빠진 다른 한자.","級(등급 급)은 給(줄 급)과 모양·음이 비슷한 다른 한자.","정답. 供給(きょうきゅう) = 공급","協(화할 협)은 「きょう」이지만 의미가 다르다."],ko: "태풍의 영향으로 전력 공급이 멈췄다.",ref: ["v:供給"]},
  {id: "hy-070",type: "hyoki",q: "この製品は値段が安いが、性能の面では他社のものに〔おとる〕。",opts: ["劣る","少る","努る","列る"],a: 0,why: ["정답. 劣る(おとる) = 뒤떨어지다","少(적을 소)는 劣(못할 렬)의 윗부분과 같은 다른 한자.","努(힘쓸 노)는 劣과 같은 力을 가진 다른 한자.","列(벌일 렬)은 劣과 음이 같은 다른 한자."],ko: "이 제품은 값은 싸지만 성능 면에서는 다른 회사 것에 뒤진다.",ref: ["v:劣る"]},
  {id: "hy-071",type: "hyoki",q: "学費を〔かせぐ〕ために、毎晩アルバイトをしている。",opts: ["嫁ぐ","架ぐ","家ぐ","稼ぐ"],a: 3,why: ["嫁ぐ는 「とつぐ」(시집가다)로 읽는 다른 말. 家 부분이 같아 헷갈린다.","架(시렁 가)는 「か」이지만 稼(심을 가)가 맞다.","家(집 가)는 稼의 오른쪽 부분일 뿐인 다른 한자.","정답. 稼ぐ(かせぐ) = (돈을) 벌다"],ko: "학비를 벌기 위해 매일 밤 아르바이트를 하고 있다.",ref: ["v:稼ぐ"]},
  {id: "hy-072",type: "hyoki",q: "高齢者のための〔ふくし〕サービスを充実させる。",opts: ["副祉","福祉","福止","復祉"],a: 1,why: ["副(버금 부)는 「ふく」이지만 福(복 복)이 맞다.","정답. 福祉(ふくし) = 복지","止(그칠 지)는 祉(복 지)의 오른쪽 부분일 뿐인 다른 한자.","復(회복할 복)은 「ふく」이지만 의미가 다르다."],ko: "고령자를 위한 복지 서비스를 충실히 한다.",ref: ["v:福祉"]},
  {id: "hy-073",type: "hyoki",q: "絶滅しそうな動物を〔ほご〕する活動が行われている。",opts: ["保穫","保護","補護","保獲"],a: 1,why: ["穫(거둘 확)은 護(도울 호)와 오른쪽 모양이 같은 다른 한자.","정답. 保護(ほご) = 보호","補(기울 보)는 「ほ」이지만 保(지킬 보)가 맞다.","獲(얻을 획)은 護와 모양이 비슷한 다른 한자."],ko: "멸종될 것 같은 동물을 보호하는 활동이 이루어지고 있다.",ref: ["v:保護"]},
  {id: "hy-074",type: "hyoki",q: "地震から十年がたち、町の〔ふっこう〕が進んでいる。",opts: ["複興","復輿","腹興","復興"],a: 3,why: ["複(겹칠 복)은 復(회복할 복)과 모양·음이 비슷한 다른 한자.","輿(수레 여)는 興(일 흥)과 모양이 매우 비슷한 다른 한자.","腹(배 복)은 復과 모양·음이 비슷한 다른 한자.","정답. 復興(ふっこう) = 부흥"],ko: "지진으로부터 10년이 지나 마을의 부흥이 진행되고 있다.",ref: ["v:復興"]},
  {id: "hy-075",type: "hyoki",q: "ボランティアとして被災地を〔しえん〕している。",opts: ["支援","支緩","支媛","枝援"],a: 0,why: ["정답. 支援(しえん) = 지원","緩(느릴 완)은 援(도울 원)과 오른쪽 모양이 같은 다른 한자.","媛(여자 원)은 援과 오른쪽 모양이 같은 다른 한자.","枝(가지 지)는 支(지탱할 지)에 木이 붙은 다른 한자."],ko: "자원봉사자로 피해 지역을 지원하고 있다.",ref: ["v:支援"]},
  {id: "hy-076",type: "hyoki",q: "卒業生が母校に図書館の本を〔きふ〕した。",opts: ["奇付","寄符","寄付","記付"],a: 2,why: ["奇(기이할 기)는 寄(부칠 기)에서 宀이 빠진 다른 한자.","符(부호 부)는 付(줄 부)에 竹이 붙은 다른 한자.","정답. 寄付(きふ) = 기부","記(기록할 기)는 「き」이지만 의미가 다르다."],ko: "졸업생이 모교에 도서관 책을 기부했다.",ref: ["v:寄付"]},
  {id: "hy-077",type: "hyoki",q: "歯の〔ちりょう〕のために、毎週病院に通っている。",opts: ["治僚","知療","治量","治療"],a: 3,why: ["僚(동료 료)는 療(병 고칠 료)와 모양·음이 비슷한 다른 한자.","知(알 지)는 「ち」이지만 治(다스릴 치)가 맞다.","量(헤아릴 량)은 「りょう」이지만 의미가 다르다.","정답. 治療(ちりょう) = 치료"],ko: "이 치료를 위해 매주 병원에 다니고 있다.",ref: ["v:治療"]},
  {id: "hy-078",type: "hyoki",q: "二人の争いは、ついに〔さいばん〕で争われることになった。",opts: ["栽判","載判","裁判","裁版"],a: 2,why: ["栽(심을 재)는 裁(마를 재)와 모양·음이 비슷한 다른 한자.","載(실을 재)는 裁와 모양·음이 비슷한 다른 한자.","정답. 裁判(さいばん) = 재판","版(판목 판)은 「はん」이지만 判(판단할 판)이 맞다."],ko: "두 사람의 다툼은 결국 재판으로 다투게 되었다.",ref: ["v:裁判"]},
  {id: "hy-079",type: "hyoki",q: "その事件はテレビで大きく〔ほうどう〕された。",opts: ["報堂","報道","包道","報動"],a: 1,why: ["堂(집 당)은 「どう」이지만 道(길 도)가 맞다.","정답. 報道(ほうどう) = 보도","包(쌀 포)는 「ほう」이지만 報(갚을 보)가 맞다.","動(움직일 동)은 「どう」이지만 의미가 다르다."],ko: "그 사건은 텔레비전에서 크게 보도되었다.",ref: ["v:報道"]},
  {id: "hy-080",type: "hyoki",q: "新聞記者が、事故について住民に〔しゅざい〕していた。",opts: ["取材","取財","取在","趣材"],a: 0,why: ["정답. 取材(しゅざい) = 취재","財(재물 재)는 材(재목 재)와 모양·음이 비슷한 다른 한자.","在(있을 재)는 「ざい」이지만 材가 맞다.","趣(뜻 취)는 取(취할 취)를 품은 다른 한자."],ko: "신문 기자가 사고에 대해 주민을 취재하고 있었다.",ref: ["v:取材"]},
  {id: "hy-081",type: "hyoki",q: "この会社は新しい薬の〔かいはつ〕に力を入れている。",opts: ["開髪","開発","開撥","改発"],a: 1,why: ["髪(터럭 발)은 発(필 발)과 모양·음이 비슷한 다른 한자.","정답. 開発(かいはつ) = 개발","撥(다스릴 발)은 発과 음이 같은 다른 한자.","改(고칠 개)는 「かい」이지만 開(열 개)가 맞다."],ko: "이 회사는 새로운 약 개발에 힘을 쏟고 있다.",ref: ["v:開発"]},
  {id: "hy-082",type: "hyoki",q: "交通ルールに〔いはん〕すると、罰金を払わなければならない。",opts: ["違反","偉反","違判","違返"],a: 0,why: ["정답. 違反(いはん) = 위반","偉(클 위)는 違(어긋날 위)와 모양·음이 비슷한 다른 한자.","判(판단할 판)은 「はん」이지만 反(돌이킬 반)이 맞다.","返(돌이킬 반)은 反에 辶이 붙은 다른 한자."],ko: "교통 규칙을 위반하면 벌금을 내야 한다.",ref: ["v:違反"]},
  {id: "hy-083",type: "hyoki",q: "来年から新しい〔せいど〕が導入される。",opts: ["製度","制渡","正度","制度"],a: 3,why: ["製(지을 제)는 制(절제할 제)에 衣가 붙은 다른 한자.","渡(건널 도)는 度(법도 도)에 氵가 붙은 다른 한자.","正(바를 정)은 「せい」이지만 制가 맞다.","정답. 制度(せいど) = 제도"],ko: "내년부터 새 제도가 도입된다.",ref: ["v:制度"]},
  {id: "hy-084",type: "hyoki",q: "失敗の〔せきにん〕は、すべて私にあります。",opts: ["積任","責妊","責任","債任"],a: 2,why: ["積(쌓을 적)은 責(꾸짖을 책)에 禾가 붙은 다른 한자.","妊(아이 밸 임)은 任(맡길 임)과 모양·음이 비슷한 다른 한자.","정답. 責任(せきにん) = 책임","債(빚 채)는 責에 亻이 붙은 다른 한자."],ko: "실패의 책임은 모두 저에게 있습니다.",ref: ["v:責任"]},
  {id: "hy-085",type: "hyoki",q: "この村では、昔からの〔でんとう〕が大切に守られている。",opts: ["伝続","電統","伝統","伝総"],a: 2,why: ["続(이을 속)은 統(거느릴 통)과 모양이 비슷한 다른 한자.","電(번개 전)은 「でん」이지만 伝(전할 전)이 맞다.","정답. 伝統(でんとう) = 전통","総(다 총)은 統과 모양이 비슷한 다른 한자."],ko: "이 마을에서는 예로부터의 전통이 소중히 지켜지고 있다.",ref: ["v:伝統"]},
  {id: "hy-086",type: "hyoki",q: "性別による〔さべつ〕をなくさなければならない。",opts: ["差列","佐別","差弁","差別"],a: 3,why: ["列(벌일 렬)은 別(나눌 별)과 모양이 비슷한 다른 한자.","佐(도울 좌)는 「さ」이지만 差(다를 차)가 맞다.","弁(고깔 변)은 「べん」이며 別과 다른 한자.","정답. 差別(さべつ) = 차별"],ko: "성별에 따른 차별을 없애야 한다.",ref: ["v:差別"]},
  {id: "hy-087",type: "hyoki",q: "すべての人は法の下に〔びょうどう〕である。",opts: ["平等","病等","平同","平導"],a: 0,why: ["정답. 平等(びょうどう) = 평등","病(병 병)은 「びょう」이지만 平(평평할 평)이 맞다.","同(한가지 동)은 「どう」이지만 等(무리 등)이 맞다.","導(인도할 도)는 「どう」이지만 의미가 다르다."],ko: "모든 사람은 법 앞에 평등하다.",ref: ["v:平等"]},
  {id: "hy-088",type: "hyoki",q: "駅前の店で、アルバイトを〔ぼしゅう〕している。",opts: ["暮集","募集","募週","墓集"],a: 1,why: ["暮(저물 모)는 募(모을 모)와 위쪽 모양이 같은 다른 한자.","정답. 募集(ぼしゅう) = 모집","週(주일 주)는 「しゅう」이지만 集(모을 집)이 맞다.","墓(무덤 묘)는 募와 위쪽 모양이 같은 다른 한자."],ko: "역 앞 가게에서 아르바이트를 모집하고 있다.",ref: ["v:募集"]},
  {id: "hy-089",type: "hyoki",q: "面接の前に〔りれきしょ〕を郵送してください。",opts: ["覆歴書","履暦書","履歴所","履歴書"],a: 3,why: ["覆(뒤집힐 복)은 履(밟을 리)와 모양이 비슷한 다른 한자.","暦(책력 력)은 歴(지날 력)과 모양·음이 비슷한 다른 한자.","所(바 소)는 「しょ」이지만 書(글 서)가 맞다.","정답. 履歴書(りれきしょ) = 이력서"],ko: "면접 전에 이력서를 우편으로 보내 주세요.",ref: ["v:履歴書"]},
  {id: "hy-090",type: "hyoki",q: "今週は毎日〔ざんぎょう〕で、帰りが遅くなった。",opts: ["惨業","残業","残行","桟業"],a: 1,why: ["惨(참혹할 참)은 残(남을 잔)과 음이 같은 다른 한자.","정답. 残業(ざんぎょう) = 잔업, 야근","行(다닐 행)은 「ぎょう」로도 읽지만 業(업 업)이 맞다.","桟(잔도 잔)은 残과 모양·음이 비슷한 다른 한자."],ko: "이번 주는 매일 야근이라 귀가가 늦어졌다.",ref: ["v:残業"]},
  {id: "hy-091",type: "hyoki",q: "仕事が終わってから、〔どうりょう〕と食事に行った。",opts: ["同療","同寮","同僚","動僚"],a: 2,why: ["療(병 고칠 료)는 僚(동료 료)와 모양·음이 비슷한 다른 한자.","寮(기숙사 료)는 僚와 모양·음이 비슷한 다른 한자.","정답. 同僚(どうりょう) = 동료","動(움직일 동)은 「どう」이지만 同(한가지 동)이 맞다."],ko: "일이 끝난 뒤 동료와 식사하러 갔다.",ref: ["v:同僚"]},
  {id: "hy-092",type: "hyoki",q: "この商品は、インターネットでも〔はんばい〕されている。",opts: ["販売","飯売","販買","版売"],a: 0,why: ["정답. 販売(はんばい) = 판매","飯(밥 반)은 販(팔 판)과 모양·음이 비슷한 다른 한자.","買(살 매)는 売(팔 매)와 의미가 반대인 다른 한자.","版(판목 판)은 販과 모양·음이 비슷한 다른 한자."],ko: "이 상품은 인터넷에서도 판매되고 있다.",ref: ["v:販売"]},
  {id: "hy-093",type: "hyoki",q: "今年は〔よさん〕が足りなくて、計画を変更した。",opts: ["予算","予参","余算","予産"],a: 0,why: ["정답. 予算(よさん) = 예산","参(참여할 참)은 「さん」이지만 算(셈 산)이 맞다.","余(남을 여)는 「よ」이지만 予(미리 예)가 맞다.","産(낳을 산)은 「さん」이지만 의미가 다르다."],ko: "올해는 예산이 부족해서 계획을 변경했다.",ref: ["v:予算"]},
  {id: "hy-094",type: "hyoki",q: "工場の火事で、会社は大きな〔そんしつ〕を出した。",opts: ["損矢","損室","損失","尊失"],a: 2,why: ["矢(화살 시)는 失(잃을 실)과 모양이 비슷한 다른 한자.","室(방 실)은 「しつ」이지만 失이 맞다.","정답. 損失(そんしつ) = 손실","尊(높을 존)은 「そん」이지만 損(덜 손)이 맞다."],ko: "공장 화재로 회사는 큰 손실을 입었다.",ref: ["v:損失"]},
  {id: "hy-095",type: "hyoki",q: "月末に、取引先に〔せいきゅうしょ〕を送った。",opts: ["清求書","請求書","請救書","請球書"],a: 1,why: ["清(맑을 청)은 請(청할 청)과 오른쪽 모양이 같은 다른 한자.","정답. 請求書(せいきゅうしょ) = 청구서","救(구원할 구)는 求(구할 구)에 攵이 붙은 다른 한자.","球(공 구)는 求에 王이 붙은 다른 한자."],ko: "월말에 거래처에 청구서를 보냈다.",ref: ["v:請求書"]},
  {id: "hy-096",type: "hyoki",q: "会議で新しい企画を〔ていあん〕した。",opts: ["堤案","提安","低案","提案"],a: 3,why: ["堤(둑 제)는 提(끌 제)와 모양·음이 비슷한 다른 한자.","安(편안 안)은 案(책상 안)의 윗부분과 같은 다른 한자.","低(낮을 저)는 「てい」이지만 提(끌 제)가 맞다.","정답. 提案(ていあん) = 제안"],ko: "회의에서 새로운 기획을 제안했다.",ref: ["v:提案"]},
  {id: "hy-097",type: "hyoki",q: "会社の〔ほうしん〕が大きく変わった。",opts: ["方針","方真","芳針","方新"],a: 0,why: ["정답. 方針(ほうしん) = 방침","真(참 진)은 「しん」이지만 針(바늘 침)이 맞다.","芳(꽃다울 방)은 方에 艹가 붙은 다른 한자.","新(새 신)은 「しん」이지만 의미가 다르다."],ko: "회사의 방침이 크게 바뀌었다.",ref: ["v:方針"]},
  {id: "hy-098",type: "hyoki",q: "レポートは金曜日までに〔ていしゅつ〕してください。",opts: ["堤出","提出","停出","程出"],a: 1,why: ["堤(둑 제)는 提(끌 제)와 모양·음이 비슷한 다른 한자.","정답. 提出(ていしゅつ) = 제출","停(머무를 정)은 「てい」이지만 의미가 다르다.","程(정도 정)은 「てい」이지만 提가 맞다."],ko: "리포트는 금요일까지 제출해 주세요.",ref: ["v:提出"]},
  {id: "hy-099",type: "hyoki",q: "この計画は、まだ社長の〔しょうにん〕を得ていない。",opts: ["承忍","承任","承認","招認"],a: 2,why: ["忍(참을 인)은 認(알 인)에서 言이 빠진 다른 한자.","任(맡길 임)은 「にん」이지만 認이 맞다.","정답. 承認(しょうにん) = 승인","招(부를 초)는 「しょう」이지만 承(이을 승)이 맞다."],ko: "이 계획은 아직 사장의 승인을 받지 못했다.",ref: ["v:承認"]},
  {id: "hy-100",type: "hyoki",q: "値段について、相手の会社と〔こうしょう〕を続けている。",opts: ["交歩","交捗","効渉","交渉"],a: 3,why: ["歩(걸음 보)는 渉(건널 섭)에서 氵가 빠진 다른 한자.","捗(칠 척)은 渉와 모양이 비슷한 다른 한자.","効(본받을 효)는 「こう」이지만 交(사귈 교)가 맞다.","정답. 交渉(こうしょう) = 교섭, 협상"],ko: "가격에 대해 상대 회사와 협상을 계속하고 있다.",ref: ["v:交渉"]},
];
